# De-RAS help source (bilingual). Run tools/help/build_help.py to produce
# resources/help/help.json (used by the app's ⓘ buttons and help window)
# and docs/manual/help-topics.{id,en}.md (manual chapter). One source, two outputs.
#
# Each topic: id -> dict(t=(title_id, title_en), s=(short_id, short_en),
#   p=(purpose_id, purpose_en), steps=([id...],[en...]), d=(data_id, data_en),
#   r=(result_id, result_en), st=status, rel=[related ids])
# status: available | partial | unavailable

T = {}
def topic(id, t, s, p=("", ""), steps=([], []), d=("", ""), r=("", ""), st="available", rel=()):
    T[id] = dict(t=t, s=s, p=p, steps=steps, d=d, r=r, st=st, rel=list(rel))

def NA(m):
    return ("Belum tersedia. Dijadwalkan untuk %s. Lihat Bantuan → Matriks fitur." % m, "Not available yet. Planned for %s. See Help → Feature matrix." % m)

# ---------------- start / hub ----------------
topic("start", ("Memulai De-RAS", "Getting started with De-RAS"),
      ("Alur kerja dasar: proyek → geometri → aliran → plan → jalankan → hasil.", "Basic workflow: project → geometry → flow → plan → run → results."),
      ("De-RAS menghitung muka air sungai 1D steady (rezim subkritis, superkritis, atau campuran) dan memakai file proyek HEC-RAS (.prj, .g##, .f##, .p##) sebagai format aslinya. Proyek yang disimpan De-RAS tetap bisa dibuka di HEC-RAS, dan sebaliknya untuk fitur yang didukung.",
       "De-RAS computes 1D steady water surface profiles (subcritical, supercritical or mixed regime) and uses HEC-RAS project files (.prj, .g##, .f##, .p##) as its native format. Projects saved by De-RAS can still be opened in HEC-RAS, and vice versa for supported features."),
      (["Di Beranda (tombol rumah atau Ctrl+1), buat proyek baru (Ctrl+N), buka file .prj (Ctrl+O), atau buka proyek contoh.", "Buka Data Geometri (Ctrl+2); klik ganda penampang untuk membuka Editor Penampang.", "Isi debit dan kondisi batas hilir di Aliran Steady (Ctrl+3).", "Periksa plan di Analisis Steady (Ctrl+5), lalu tekan F7 (Model Doctor) dan F5 (Hitung).", "Jendela Komputasi menampilkan kemajuan; setelah selesai klik Lihat hasil.", "Di Hasil, lihat penampang, profil memanjang dan tabel; ekspor CSV atau laporan HTML."],
       ["On Home, create a new project (Ctrl+N), open a .prj file (Ctrl+O), or open the example project.", "Open Geometric Data (Ctrl+2); double-click a cross section to open the Cross Section Editor.", "Enter discharges and downstream boundaries in Steady Flow (Ctrl+3).", "Check the plan in Steady Analysis (Ctrl+5), then press F7 (Model Doctor) and F5 (Compute).", "The Compute window shows progress; when it finishes click View results.", "In Results, review cross sections, the longitudinal profile and tables; export CSV or an HTML report."]),
      ("Penampang melintang (stasiun–elevasi), n Manning, jarak antarpenampang, debit per profil, kondisi batas hilir.", "Cross sections (station–elevation), Manning's n, reach lengths, discharge per profile, downstream boundary."),
      ("Muka air, garis energi, kecepatan, luas, lebar muka air, dan bilangan Froude per penampang. Hasil belum dibandingkan dengan HEC-RAS.", "Water surface, energy grade, velocity, area, top width and Froude number per cross section. Equivalence with HEC-RAS has not been validated."),
      rel=["hub.new", "geometry.editor", "flow.editor", "plan.editor", "sim.run", "results.view"])
topic("hub.new", ("Proyek baru", "New project"), ("Membuat proyek HEC-RAS baru dari satu lembar isian (Ctrl+N).", "Creates a new HEC-RAS project from a single form (Ctrl+N)."),
      ("Membuat file .prj, .g01, .f01 dan .p01 di folder pilihan Anda.", "Creates .prj, .g01, .f01 and .p01 files in the folder you choose."),
      (["Klik Proyek baru di Beranda atau Berkas → Proyek baru.", "Bagian 1: isi judul, nama file dan folder.", "Bagian 2: pilih satuan, sistem koordinat dan zona waktu.", "Bagian 3: isi nama sungai dan reach, lalu pilih template kosong atau saluran prismatik.", "Klik Buat proyek."],
       ["Click New project on Home or File → New project.", "Section 1: enter a title, file name and folder.", "Section 2: choose units, coordinate system and time zone.", "Section 3: enter river and reach names, then choose an empty or prismatic-channel template.", "Click Create project."]),
      ("Nama file tanpa spasi; folder yang bisa ditulisi.", "A file name without spaces; a writable folder."),
      ("Proyek baru langsung terbuka: template prismatik di Beranda, template kosong di Data Geometri. De-RAS tidak pernah menimpa proyek yang sudah ada.", "The new project opens right away: the prismatic template on Home, the empty template in Geometric Data. De-RAS never overwrites an existing project."), rel=["wizard.page1", "hub.example"])
topic("hub.open", ("Buka proyek", "Open project"), ("Membuka file .prj HEC-RAS beserta file geometri, aliran dan plan yang tercantum.", "Opens a HEC-RAS .prj file with the geometry, flow and plan files it lists."),
      ("De-RAS membaca semua file yang tercantum di .prj. Bagian yang belum didukung (misalnya jembatan) tetap tersimpan utuh saat proyek disimpan.", "De-RAS reads every file listed in the .prj. Parts it does not support yet (e.g. bridges) are kept unchanged when saving."),
      (["Klik Buka proyek.", "Pilih file .prj.", "Periksa panel Pesan untuk peringatan pembacaan."], ["Click Open project.", "Choose the .prj file.", "Check the Messages panel for read warnings."]),
      ("File .prj dan file-file yang dirujuknya di folder yang sama.", "The .prj file and the files it references in the same folder."),
      ("Proyek terbuka; file yang tidak diubah ditulis ulang byte demi byte sama.", "The project opens; unchanged files are written back byte-for-byte identical."), rel=["hub.recent", "project.save"])
topic("hub.duplicate", ("Duplikasi proyek", "Duplicate project"), ("Menyalin semua file proyek ke nama atau folder baru (Simpan Sebagai).", "Copies all project files to a new name or folder (Save As)."),
      ("Berguna untuk membuat skenario tanpa mengubah proyek asli.", "Useful for creating scenarios without changing the original project."),
      (["Klik Duplikasi.", "Pilih nama .prj baru.", "Proyek salinan terbuka otomatis."], ["Click Duplicate.", "Choose a new .prj name.", "The copy opens automatically."]),
      ("Proyek sumber (yang terbuka atau dipilih).", "The source project (open or chosen)."), ("Salinan lengkap dengan nama file baru.", "A complete copy with the new file names."))
topic("hub.example", ("Proyek contoh", "Example project"), ("Membuka proyek uji standar De-RAS (Sungai Uji 1 km) berlabel CONTOH.", "Opens the De-RAS standard test project (Sungai Uji 1 km), labelled EXAMPLE."),
      ("Sungai 1 km dengan 6 penampang setiap 200 m, saluran utama lebar 20 m, dan debit 20, 60, serta 150 m³/s. Data buatan untuk belajar dan untuk menguji setiap fitur analisis, bukan data lapangan.", "A 1 km river with 6 cross sections every 200 m, a 20 m wide main channel, and flows of 20, 60 and 150 m³/s. Made-up data for learning and for testing every analysis feature, not field data."),
      (["Klik Proyek contoh di Beranda.", "Tekan F5 untuk menghitung.", "Klik Lihat hasil di Jendela Komputasi."], ["Click Example project on Home.", "Press F5 to compute.", "Click View results in the Compute window."]),
      r=("Proyek DerasUji1km di Dokumen\\De-RAS Projects\\Contoh. Salinan yang sudah ada tidak ditimpa.", "Project DerasUji1km in Documents\\De-RAS Projects\\Contoh. An existing copy is not overwritten."))
topic("hub.recent", ("Proyek terakhir", "Recent projects"), ("Daftar proyek yang terakhir dibuka atau disimpan. Klik ganda untuk membuka.", "Projects opened or saved recently. Double-click to open."),
      ("Tanda ⚠ berarti file tidak ditemukan (dipindah atau dihapus).", "A ⚠ mark means the file was not found (moved or deleted)."))

