# ---------------- project ----------------
topic("project.save", ("Simpan proyek", "Save project"), ("Menyimpan semua file yang berubah dalam format HEC-RAS (Ctrl+S).", "Saves every changed file in HEC-RAS format (Ctrl+S)."),
      ("Hanya file yang berubah yang ditulis ulang. De-RAS menulis ke file sementara dulu lalu menggantinya, jadi file lama tidak rusak kalau penyimpanan gagal. Bagian file yang tidak dikenal tetap tersimpan.", "Only changed files are rewritten, atomically (temporary file then replace), so the old file is not damaged if saving fails. Unknown parts of files are preserved."))
topic("project.close", ("Tutup proyek", "Close project"), ("Menutup proyek dan kembali ke Beranda. Anda akan ditanya bila ada perubahan belum disimpan.", "Closes the project and returns to the start page. You are asked if there are unsaved changes."))
topic("project.folder", ("Folder proyek", "Project folder"), ("Membuka folder proyek di Windows Explorer.", "Opens the project folder in Windows Explorer."))


# ---------------- geometry ----------------
topic("geometry.editor", ("Editor Penampang", "Cross Section Editor"), ("Mengedit reach dan penampang melintang 1D: stasiun–elevasi, n Manning, jarak, tebing dan koefisien.", "Edit reaches and 1D cross sections: station–elevation, Manning's n, lengths, banks and coefficients."),
      ("Setiap perubahan langsung terlihat di plot dan masuk ke file .g## saat Anda menyimpan (Ctrl+S).", "All edits go straight into the .g## model and are saved with Ctrl+S. The cross-section plot updates immediately."),
      (["Dari Data Geometri, klik ganda penampang di kanvas atau klik Penampang di palet.", "Pilih reach dan RS di baris atas; PgUp/PgDn pindah ke penampang sebelum/berikutnya.", "Edit tabel stasiun–elevasi; tempel dari Excel dengan Ctrl+V.", "Isi jarak ke penampang hilir, tebing, n Manning dan koefisien di kartu Data penampang.", "Tambah, salin atau hapus penampang dengan tombol di baris atas; simpan dengan Ctrl+S."],
       ["From Geometric Data, double-click a cross section on the canvas or click Cross section in the palette.", "Choose the reach and RS in the top row; PgUp/PgDn move to the previous/next section.", "Edit the station–elevation table; paste from Excel with Ctrl+V.", "Enter downstream lengths, banks, Manning's n and coefficients in the Section data card.", "Add, copy or delete sections with the buttons in the top row; save with Ctrl+S."]),
      ("Data survei penampang; nilai n Manning; jarak antarpenampang (kiri, alur, kanan).", "Cross-section survey data; Manning's n values; reach lengths (left, channel, right)."),
      ("File .g## yang bisa dibuka HEC-RAS.", "A .g## file that HEC-RAS can open."), rel=["geometry.staelev", "geometry.manning", "geometry.lengths", "geometry.banks"])
topic("geometry.reach", ("Reach", "Reach"), ("Ruas sungai berisi penampang berurutan. Tambah atau ganti nama reach; nama sungai/reach maks. 16 karakter.", "A river segment holding ordered cross sections. Add or rename reaches; river/reach names max. 16 characters."),
      ("Mengganti nama reach juga memperbarui rujukan di data aliran.", "Renaming a reach also updates the references in the flow data."), rel=["geometry.editor"])
topic("geometry.xslist", ("Daftar penampang", "Cross-section list"), ("Penampang reach ini, berurutan dari hulu (RS terbesar) ke hilir.", "Cross sections of this reach, ordered upstream (largest RS) to downstream."),
      ("Jembatan, gorong-gorong, dan struktur inline ikut ditampilkan dan diedit dari palet (klik dua kali tanda struktur di kanvas). Struktur lain tetap tersimpan di file tetapi belum dihitung.", "Bridges, culverts and inline structures are shown and edited from the palette (double-click the structure mark on the canvas). Other structures are kept in the file but not computed yet."))
topic("geometry.import", ("Impor survei CSV", "Import survey CSV"), ("Mengimpor penampang dari CSV: RS, stasiun, elevasi per baris.", "Imports cross sections from CSV: RS, station, elevation per row."),
      ("Setiap RS baru menjadi penampang baru di reach terpilih; n Manning, jarak dan tebing perlu dilengkapi setelahnya.", "Each new RS becomes a new cross section in the selected reach; Manning's n, lengths and banks must be completed afterwards."),
      (["Siapkan CSV dengan kolom RS,Station,Elevation (desimal titik atau koma).", "Klik Impor survei CSV dan pilih file.", "Periksa ringkasan, lalu lengkapi data penampang."], ["Prepare a CSV with columns RS,Station,Elevation (dot or comma decimals).", "Click Import survey CSV and choose the file.", "Check the summary, then complete the cross-section data."]))
topic("geometry.rs", ("River Station (RS)", "River Station (RS)"), ("Nomor penanda penampang. Angka yang lebih besar berarti lebih ke hulu.", "Cross-section identifier. A larger number is further upstream."))
topic("geometry.description", ("Deskripsi", "Description"), ("Catatan bebas untuk penampang ini (disimpan di file .g##).", "Free notes for this cross section (stored in the .g## file)."))
topic("geometry.lengths", ("Jarak ke penampang hilir", "Downstream reach lengths"), ("Jarak dari penampang ini ke penampang berikutnya di hilir, untuk bantaran kiri, alur utama dan bantaran kanan.", "Distance from this section to the next one downstream, for the left overbank, main channel and right overbank."),
      ("Dipakai untuk menghitung kehilangan gesek dengan jarak berbobot debit. Penampang paling hilir boleh 0.", "Used to compute friction loss with a discharge-weighted length. The most downstream section may be 0."))
topic("geometry.banks", ("Stasiun tebing", "Bank stations"), ("Stasiun tebing kiri dan kanan yang memisahkan bantaran dan alur utama.", "Left and right bank stations separating the overbanks from the main channel."),
      ("Harus berada di antara titik stasiun–elevasi pertama dan terakhir. Model Doctor memeriksa kesesuaiannya.", "Must lie between the first and last station–elevation points. Model Doctor checks them."))
topic("geometry.coefficients", ("Koefisien kontraksi dan ekspansi", "Contraction and expansion coefficients"), ("Koefisien kehilangan akibat perubahan tinggi kecepatan. Umum: 0,1 dan 0,3.", "Loss coefficients for changes in velocity head. Typical: 0.1 and 0.3."),
      ("Kehilangan = C × |Δ(αV²/2g)|. Kontraksi bila tinggi kecepatan hilir lebih besar, ekspansi bila lebih kecil.", "Loss = C × |Δ(αV²/2g)|. Contraction when the downstream velocity head is larger, expansion when smaller."))
topic("geometry.staelev", ("Tabel stasiun–elevasi", "Station–elevation table"), ("Titik penampang dari kiri ke kanan (menghadap hilir). Stasiun harus tidak menurun.", "Cross-section points from left to right (looking downstream). Stations must not decrease."),
      ("Sel merah berisi nilai yang tidak valid dan tidak disimpan; nilai lama tetap dipakai. Data bisa ditempel dari Excel.", "Red cells hold invalid values that are not stored; the previous value is kept. Pasting from Excel is supported."))
topic("geometry.manning", ("Tabel n Manning", "Manning's n table"), ("Titik ubah n Manning: mulai dari stasiun ini ke kanan berlaku nilai n tersebut.", "Manning's n breakpoints: from this station to the right the given n applies."),
      ("Bantaran dibagi di setiap titik ubah n; alur utama memakai n komposit bila ada lebih dari satu nilai.", "Overbanks are subdivided at each n breakpoint; the main channel uses a composite n when it has more than one value."))
topic("geometry.plot", ("Plot penampang", "Cross-section plot"), ("Tampilan penampang dengan posisi tebing dan titik ubah n. Arahkan kursor untuk membaca koordinat.", "Cross-section view with bank positions and n breakpoints. Hover to read coordinates."))
topic("geometry.col.station", ("Kolom Stasiun", "Station column"), ("Jarak horizontal dari titik acuan kiri, dalam satuan panjang proyek.", "Horizontal distance from the left reference, in project length units."))
topic("geometry.col.elevation", ("Kolom Elevasi", "Elevation column"), ("Elevasi tanah pada stasiun tersebut, dalam satuan panjang proyek.", "Ground elevation at that station, in project length units."))
topic("geometry.col.nstation", ("Kolom Stasiun n", "n Station column"), ("Stasiun awal berlakunya nilai n.", "Station where the n value starts to apply."))
topic("geometry.col.nvalue", ("Kolom nilai n", "n value column"), ("Koefisien kekasaran Manning (tanpa satuan), mis. 0,03 untuk alur alami bersih.", "Manning's roughness coefficient (dimensionless), e.g. 0.03 for a clean natural channel."))
topic("geometry.structures", ("Struktur", "Structures"), ("Jembatan, gorong-gorong, dan struktur inline (bendung dengan pintu) diedit dari palet Data Geometri dan dihitung pada rezim subkritis. Struktur lateral, bukaan ganda, dan pompa belum tersedia.", "Bridges, culverts and inline structures (weirs with gates) are edited from the Geometric Data palette and computed in the subcritical regime. Lateral structures, multiple openings and pumps are not available yet."),
      ("Struktur ditempatkan di antara dua penampang menurut river station-nya. Penampang hulu dan hilir dipakai sebagai batas hitungan; jarak penampang hulu ke penampang hilir tetap diisi di penampang hulu.", "A structure sits between two cross sections by its river station. The upstream and downstream sections bound the computation; the length from the upstream to the downstream section stays on the upstream section."),
      r=("Status Pratinjau: hasil belum dibandingkan dengan HEC-RAS, dan format blok struktur di file .g## belum diverifikasi. Struktur yang tidak terbaca tetap disimpan utuh dan Model Doctor menolak run.", "Preview status: results are not compared with HEC-RAS yet and the structure block format in the .g## file is not verified. Structures that cannot be read are kept unchanged and Model Doctor refuses the run."),
      st="preview", rel=["geometry.bridge", "geometry.culvert", "geometry.inline"])
SV = ("Status Pratinjau: belum dibandingkan dengan HEC-RAS; format blok di file .g## belum diverifikasi. Hanya rezim subkritis.", "Preview status: not compared with HEC-RAS yet; the block format in the .g## file is not verified. Subcritical regime only.")
topic("geometry.bridge", ("Jembatan", "Bridge"), ("Jembatan dengan dek, pilar, dan aliran di atas dek.", "A bridge with deck, piers and flow over the deck."),
      ("Aliran rendah (muka air di bawah dek): metode energi melalui penampang di dalam jembatan dengan pilar sebagai penghalang, dan rumus Yarnell (K = 1,25); hasil dengan energi tertinggi dipakai. Aliran tinggi: rumus sluice gate (Cd dari rasio Y3/Z) atau orifice (C = 0,8) bila sisi hilir dek terendam, ditambah aliran pelimpah di atas dek dengan reduksi terendam Villemonte.", "Low flow (water below the deck): energy method through sections inside the bridge with piers as obstructions, and the Yarnell equation (K = 1.25); the highest energy answer is used. High flow: sluice gate equation (Cd from Y3/Z) or orifice (C = 0.8) when the downstream low chord is submerged, plus weir flow over the deck with Villemonte submergence."),
      (["Buka Data Geometri, klik Jembatan / Gorong-gorong di palet.", "Pilih reach, klik Tambah jembatan.", "Isi river station (di antara dua penampang), jarak ke muka hulu, lebar dek, dan koefisien pelimpah.", "Isi tabel dek (stasiun, elevasi atas, elevasi bawah) dan pilar.", "Klik Tambah, lalu simpan proyek."],
       ["Open Geometric Data, click Bridge / Culvert in the palette.", "Pick the reach, click Add bridge.", "Enter the river station (between two sections), distance to the upstream face, deck width and weir coefficient.", "Fill the deck table (station, high chord, low chord) and the piers.", "Click Add, then save the project."]),
      ("Blok Type RM = 3 dengan baris Bridge Culvert-, Deck Dist Width WeirC, dan Pier di file .g##.", "A Type RM = 3 block with Bridge Culvert-, Deck Dist Width WeirC and Pier lines in the .g## file."),
      SV, st="preview", rel=["geometry.structures", "geometry.col.deck", "geometry.col.pier"])
topic("geometry.culvert", ("Gorong-gorong", "Culvert"), ("Gorong-gorong lingkaran atau kotak di bawah timbunan jalan.", "Circular or box culverts under a road embankment."),
      ("Energi hulu adalah yang terbesar dari kontrol inlet (persamaan FHWA HDS-5 bentuk 1, chart 1, 2, 8 dan scale 1–3, dengan transisi tak terendam/terendam antara 3,5 dan 4,0) dan kontrol outlet (kehilangan masuk, gesekan, dan keluar dengan aliran penuh di atas maks(TW, (dc + D)/2)). Aliran di atas jalan dihitung sebagai pelimpah.", "The upstream energy is the larger of inlet control (FHWA HDS-5 form 1 equations, charts 1, 2, 8 and scales 1–3, with the unsubmerged/submerged transition between 3.5 and 4.0) and outlet control (entrance, friction and exit losses with full flow above max(TW, (dc + D)/2)). Flow over the road is computed as weir flow."),
      (["Klik Jembatan / Gorong-gorong di palet, lalu Tambah gorong-gorong.", "Isi tabel jalan (elevasi atas = elevasi bawah untuk timbunan).", "Isi satu baris per kelompok barrel identik: bentuk, bentang, tinggi, panjang, n, Ke, Kx, chart, scale, invert, dan stasiun barrel.", "Klik Tambah."],
       ["Click Bridge / Culvert in the palette, then Add culvert.", "Fill the road table (high chord = low chord for an embankment).", "Enter one row per group of identical barrels: shape, span, rise, length, n, Ke, Kx, chart, scale, inverts and barrel stations.", "Click Add."]),
      ("Baris Culvert= di blok Type RM = 2 file .g## (satu baris per barrel).", "Culvert= lines in a Type RM = 2 block of the .g## file (one line per barrel)."),
      SV, st="preview", rel=["geometry.structures", "geometry.col.culvert"])
topic("geometry.inline", ("Struktur inline", "Inline structure"), ("Bendung atau pelimpah melintang sungai, dengan atau tanpa pintu.", "A weir or spillway across the river, with or without gates."),
      ("Aliran dibagi antara mercu pelimpah (Q = C L H^1,5, reduksi terendam Villemonte; bukaan pintu tidak ikut) dan pintu: sluice gate, orifice bila rasio muka air hilir di atas 0,67, atau pelimpah di atas ambang bila air belum mencapai bibir pintu. Energi hulu dicari dengan biseksi.", "Flow is split between the weir crest (Q = C L H^1.5, Villemonte submergence; gate openings excluded) and the gates: sluice gate, orifice when the tailwater ratio exceeds 0.67, or weir flow over the sill when the water does not reach the gate lip. The upstream energy is found by bisection."),
      (["Klik Struktur Inline di palet, lalu Tambah struktur inline.", "Isi tabel mercu (stasiun, elevasi).", "Isi pintu: nama, lebar, tinggi, elevasi ambang, koefisien, stasiun tengah bukaan, dan bukaan untuk run steady.", "Klik Tambah, lalu simpan proyek."],
       ["Click Inline Structure in the palette, then Add inline structure.", "Fill the crest table (station, elevation).", "Enter the gates: name, width, height, sill elevation, coefficient, opening centre stations and the opening for steady runs.", "Click Add, then save the project."]),
      ("Baris IW Dist, #Inline Weir SE=, dan IW Gate Name di blok Type RM = 5 file .g##. Bukaan pintu disimpan di <nama>.deras.json karena De-RAS belum menulis bukaan ke file aliran.", "IW Dist, #Inline Weir SE= and IW Gate Name lines in a Type RM = 5 block of the .g## file. Gate openings are stored in <name>.deras.json because De-RAS does not write them to the flow file yet."),
      SV, st="preview", rel=["geometry.structures", "geometry.col.weir", "geometry.col.gate"])
topic("geometry.col.deck", ("Kolom dek/jalan", "Deck/road columns"), ("Stasiun, elevasi atas (permukaan dek atau jalan), dan elevasi bawah (bawah dek). Untuk timbunan jalan tanpa bukaan, elevasi bawah sama dengan elevasi atas.", "Station, high chord (top of deck or road) and low chord (underside of the deck). For a road embankment without an opening the low chord equals the high chord."), st="preview")
topic("geometry.col.pier", ("Kolom pilar", "Pier columns"), ("Stasiun tengah, lebar, elevasi dasar, dan elevasi puncak pilar. Pilar mengurangi luas bukaan dan dipakai dalam rumus Yarnell.", "Centre station, width, bottom and top elevation of the pier. Piers reduce the opening area and are used in the Yarnell equation."), st="preview")
topic("geometry.col.culvert", ("Kolom gorong-gorong", "Culvert columns"), ("Satu baris per kelompok barrel identik. Jumlah barrel sama dengan jumlah stasiun barrel. Chart dan scale mengikuti tabel FHWA HDS-5.", "One row per group of identical barrels. The number of barrels equals the number of barrel stations. Chart and scale follow the FHWA HDS-5 table."), st="preview")
topic("geometry.col.weir", ("Kolom mercu", "Crest columns"), ("Stasiun dan elevasi mercu pelimpah dari kiri ke kanan.", "Station and crest elevation of the weir from left to right."), st="preview")
topic("geometry.col.gate", ("Kolom pintu", "Gate columns"), ("Lebar dan tinggi tiap bukaan, elevasi ambang, koefisien sluice/orifice, stasiun tengah tiap bukaan, dan bukaan untuk run steady (kosong = terbuka penuh).", "Width and height of each opening, sill elevation, sluice/orifice coefficient, centre station of each opening and the opening for steady runs (empty = fully open)."), st="preview")
topic("geometry.areas", ("Area khusus", "Special areas"), ("Ineffective area, levee, dan obstruction diedit dan dihitung per penampang. Storage area dan area 2D belum tersedia.", "Ineffective areas, levees and obstructions are edited and computed per cross section. Storage areas and 2D areas are not available yet."),
      ("Buka Editor Penampang, lalu tombol Ineffective, Obstruction, atau Levee di kartu Data penampang.", "Open the Cross-Section Editor, then the Ineffective, Obstruction or Levee button on the Section data card."), st="partial",
      rel=["geometry.ineffective", "geometry.obstruction", "geometry.levee"])
topic("geometry.ineffective", ("Ineffective flow area", "Ineffective flow areas"), ("Bagian penampang yang menampung air tetapi tidak ikut mengalirkannya, misalnya daerah di belakang tanggul jalan atau di samping jembatan.", "Parts of the section that hold water but do not convey it, for example behind a road embankment or beside a bridge."),
      ("Selama muka air tidak lebih tinggi dari elevasinya, air di rentang stasiun itu tidak dihitung dalam luas, keliling basah, dan konveyansi. Setelah muka air melewatinya, area ikut mengalir lagi. Area permanen tidak pernah ikut mengalir.", "While the water surface is at or below its elevation, water inside the station range is left out of area, wetted perimeter and conveyance. Once the water surface is above it, the area conveys flow again. Permanent areas never convey flow."),
      (["Buka Editor Penampang dan pilih penampang.", "Klik Ineffective di kartu Data penampang.", "Isi stasiun awal, stasiun akhir, elevasi, dan Permanen (0 atau 1) per baris.", "Klik Terapkan, lalu simpan proyek."],
       ["Open the Cross-Section Editor and pick a section.", "Click Ineffective on the Section data card.", "Enter start station, end station, elevation and Permanent (0 or 1) per row.", "Click Apply, then save the project."]),
      ("Baris #XS Ineff= dan Permanent Ineff= di file .g##.", "The #XS Ineff= and Permanent Ineff= lines of the .g## file."),
      ("Status Pratinjau: hasilnya belum dibandingkan dengan HEC-RAS.", "Preview status: results have not been compared with HEC-RAS yet."), st="preview")
topic("geometry.obstruction", ("Blocked obstruction", "Blocked obstructions"), ("Bagian penampang yang padat, misalnya bangunan atau timbunan di bantaran.", "Solid parts of the section, for example buildings or fill on the overbank."),
      ("Di rentang stasiun itu, dasar penampang dinaikkan sampai elevasi yang diisi. Luas di bawahnya hilang dan sisi tegaknya menambah keliling basah.", "Inside the station range the ground is raised to the given elevation. The area below disappears and its vertical sides add wetted perimeter."),
      (["Buka Editor Penampang dan pilih penampang.", "Klik Obstruction di kartu Data penampang.", "Isi stasiun awal, stasiun akhir, dan elevasi per baris.", "Klik Terapkan."],
       ["Open the Cross-Section Editor and pick a section.", "Click Obstruction on the Section data card.", "Enter start station, end station and elevation per row.", "Click Apply."]),
      ("Baris #Block Obstruct= di file .g##.", "The #Block Obstruct= line of the .g## file."),
      ("Status Pratinjau: hasilnya belum dibandingkan dengan HEC-RAS.", "Preview status: results have not been compared with HEC-RAS yet."), st="preview")
topic("geometry.levee", ("Levee", "Levees"), ("Tanggul di kiri atau kanan alur yang menahan air sampai puncaknya terlewati.", "An embankment left or right of the channel that holds water back until its crest is overtopped."),
      ("Air di luar levee (kiri dari levee kiri, kanan dari levee kanan) tidak ikut mengalir sampai muka air lebih tinggi dari puncak levee. Kalau puncak levee lebih tinggi dari tanah, titik itu dinaikkan ke puncak levee.", "Water beyond a levee (left of the left levee, right of the right levee) does not flow until the water surface is above the levee crest. When the crest is above the ground, the ground is raised there."),
      (["Buka Editor Penampang dan pilih penampang.", "Klik Levee di kartu Data penampang.", "Centang levee kiri dan/atau kanan, isi stasiun dan elevasi puncaknya.", "Klik Terapkan."],
       ["Open the Cross-Section Editor and pick a section.", "Click Levee on the Section data card.", "Tick the left and/or right levee and enter its station and crest elevation.", "Click Apply."]),
      ("Baris Levee= di file .g##.", "The Levee= line of the .g## file."),
      ("Status Pratinjau: hasilnya belum dibandingkan dengan HEC-RAS.", "Preview status: results have not been compared with HEC-RAS yet."), st="preview")
topic("geometry.col.blockstation", ("Kolom stasiun awal dan akhir", "Start and end station columns"), ("Rentang stasiun area, dari kiri ke kanan, menghadap hilir. Harus di dalam penampang.", "Station range of the area, left to right looking downstream. Must lie inside the section."))
topic("geometry.col.blockelev", ("Kolom elevasi", "Elevation column"), ("Untuk ineffective: muka air di atas elevasi ini membuat area ikut mengalir. Untuk obstruction: puncak bagian yang padat.", "For ineffective areas: above this water surface the area conveys flow. For obstructions: the top of the solid part."))
topic("geometry.col.permanent", ("Kolom Permanen", "Permanent column"), ("1 berarti area tidak pernah ikut mengalir, berapa pun muka airnya. 0 berarti area ikut mengalir setelah muka air melewati elevasinya.", "1 means the area never conveys flow, whatever the water surface. 0 means it conveys flow once the water surface is above its elevation."))
topic("geometry.junction", ("Junction", "Junctions"), ("Titik pertemuan atau percabangan reach.", "Where reaches join or split."),
      ("Ujung hilir reach yang masuk tersambung dengan ujung hulu reach yang keluar. Untuk aliran subkritis, muka air ujung reach yang masuk dihitung dari reach di hilirnya dengan persamaan energi melewati panjang junction; pada percabangan dipakai muka air tertinggi. Untuk aliran superkritis arahnya terbalik.", "The downstream ends of incoming reaches connect to the upstream ends of outgoing reaches. For subcritical flow the water surface at the end of an incoming reach comes from the reach below it through the energy equation over the junction length; at a split the highest water surface is used. Supercritical flow works the other way round."),
      (["Di Data Geometri, klik Junction di palet.", "Klik Tambah…, isi nama, centang reach masuk dan keluar.", "Isi panjang untuk reach di sisi yang lebih dari satu.", "Klik Terapkan, lalu Tutup."],
       ["In Geometric Data, click Junction in the palette.", "Click Add…, enter a name, tick the incoming and outgoing reaches.", "Enter lengths for the reaches on the side with more than one reach.", "Click Apply, then Close."]),
      ("Blok Junct Name= di file .g##. Debit tiap reach diisi di Aliran Steady.", "The Junct Name= block of the .g## file. Each reach's flow is entered in Steady Flow."),
      ("Ujung reach di junction tidak butuh kondisi batas. Status Pratinjau: belum dibandingkan dengan HEC-RAS.", "Reach ends at a junction need no boundary condition. Preview status: not compared with HEC-RAS yet."), st="preview")

# ---------------- flow ----------------
topic("flow.editor", ("Data aliran steady", "Steady flow data"), ("Profil, debit per lokasi dan kondisi batas hilir (file .f##).", "Profiles, discharge per location and downstream boundaries (.f## file)."),
      ("Setiap profil adalah satu skenario debit (mis. Q2, Q25, Q100) yang dihitung terpisah.", "Each profile is one discharge scenario (e.g. Q2, Q25, Q100) computed separately."),
      (["Atur jumlah profil dan namanya.", "Isi debit di setiap lokasi perubahan debit (minimal di penampang paling hulu).", "Pilih tipe batas hilir per reach dan profil, lalu isi nilainya."], ["Set the number of profiles and their names.", "Enter discharges at each flow-change location (at least the most upstream section).", "Choose the downstream boundary type per reach and profile, then enter its value."]),
      ("Debit puncak per profil; kemiringan energi hilir, elevasi muka air diketahui, atau rating curve.", "Peak discharge per profile; downstream energy slope, known water surface, or rating curve."), rel=["flow.boundary", "flow.table"])
topic("flow.profiles", ("Jumlah profil", "Number of profiles"), ("Banyaknya skenario debit yang dihitung dalam satu run.", "Number of discharge scenarios computed in one run."))
topic("flow.profilenames", ("Nama profil", "Profile names"), ("Nama tiap profil, maks. 12 karakter, tanpa koma.", "Name of each profile, max. 12 characters, no commas."))
topic("flow.table", ("Tabel debit", "Discharge table"), ("Debit tiap profil di lokasi perubahan debit. Debit berlaku ke hilir sampai lokasi berikutnya.", "Discharge per profile at flow-change locations. A discharge applies downstream until the next location."))
topic("flow.csv", ("Impor/ekspor debit CSV", "Import/export flows CSV"), ("Format: River,Reach,RS,<profil 1>,<profil 2>,… satu baris per lokasi.", "Format: River,Reach,RS,<profile 1>,<profile 2>,… one row per location."))
topic("flow.boundary", ("Kondisi batas", "Boundary conditions"), ("Kondisi di ujung hilir reach (awal hitungan subkritis) dan di ujung hulu reach (awal hitungan superkritis).", "The condition at the downstream end of a reach (start of the subcritical computation) and at its upstream end (start of the supercritical computation)."),
      ("Normal depth: masukkan kemiringan energi (mis. 0,001). Known WS: elevasi muka air. Kritis: tanpa nilai. Rating curve (hanya hilir): pasangan elevasi:debit. Ujung reach di junction tidak butuh batas.", "Normal depth: enter the energy slope (e.g. 0.001). Known WS: a water surface elevation. Critical: no value. Rating curve (downstream only): stage:flow pairs. Reach ends at a junction need no boundary."))
topic("flow.col.location", ("Lokasi debit", "Flow location"), ("Sungai, reach dan RS tempat debit ditetapkan.", "River, reach and RS where the discharge is set."))
topic("flow.col.discharge", ("Debit", "Discharge"), ("Debit profil ini di lokasi tersebut, satuan m³/s (SI) atau cfs (US).", "Discharge of this profile at that location, in m³/s (SI) or cfs (US)."))
topic("flow.col.bcreach", ("Reach / profil", "Reach / profile"), ("Reach dan profil yang diberi kondisi batas.", "Reach and profile the boundary applies to."))
topic("flow.col.bctype", ("Tipe batas", "Boundary type"), ("Normal depth, Muka air diketahui, Kedalaman kritis atau Rating curve.", "Normal depth, Known W.S., Critical depth or Rating curve."))
topic("flow.col.bcvalue", ("Nilai batas", "Boundary value"), ("Kemiringan energi (normal depth) atau elevasi muka air (known WS).", "Energy slope (normal depth) or water surface elevation (known WS)."))
topic("flow.col.bcrating", ("Rating curve", "Rating curve"), ("Pasangan elevasi:debit dipisah titik koma, mis. 101,2:50; 102,0:120.", "Stage:flow pairs separated by semicolons, e.g. 101.2:50; 102.0:120."),
      ("Format penyimpanan rating curve di file .f## belum diverifikasi terhadap HEC-RAS.", "The .f## storage format of rating curves has not been verified against HEC-RAS."), st="partial")
topic("flow.unsteady", ("Aliran unsteady", "Unsteady flow"), ("File .u## berisi kondisi batas yang berubah terhadap waktu dan debit awal. Diedit di Data Aliran Unsteady (Ctrl+4).", "A .u## file holds time-varying boundary conditions and initial flows. Edited in Unsteady Flow Data (Ctrl+4)."),
      ("Status Pratinjau: hasil belum dibandingkan dengan HEC-RAS dan format beberapa baris (Rating Curve, aliran lateral) belum diverifikasi. Baris yang tidak dikenal De-RAS disimpan apa adanya.", "Preview status: results are not compared with HEC-RAS yet and some line formats (Rating Curve, lateral inflows) are not verified. Lines De-RAS does not recognise are kept unchanged."),
      st="preview", rel=["view.unsteady", "view.run-unsteady"])

# ---------------- plan / simulation ----------------
topic("plan.editor", ("Plan", "Plan"), ("Plan menggabungkan satu geometri dan satu data aliran dengan pengaturan perhitungan.", "A plan combines one geometry and one flow file with computation settings."),
      ("Plan diatur di Analisis Steady (Ctrl+5). Run memakai file yang tersimpan di disk; De-RAS menyimpan otomatis sebelum run.", "Plans are set up in Steady Analysis (Ctrl+5). A run uses the files on disk; De-RAS saves automatically before running."),
      (["Pilih plan atau buat plan baru dengan tombol +.", "Pilih file geometri dan aliran.", "Periksa toleransi dan metode kemiringan gesek.", "Tekan F7 lalu F5."], ["Choose a plan or create a new one with the + button.", "Choose the geometry and flow files.", "Check tolerances and the friction slope method.", "Press F7 then F5."]))
topic("plan.title", ("Judul plan", "Plan title"), ("Nama plan yang tampil di daftar plan.", "Plan name shown in the plan list."))
topic("plan.shortid", ("ID singkat", "Short ID"), ("Pengenal singkat plan (Short Identifier di HEC-RAS).", "Short plan identifier (Short Identifier in HEC-RAS)."))
topic("plan.files", ("File plan", "Plan files"), ("File geometri (.g##) dan aliran steady (.f##) yang dipakai plan.", "Geometry (.g##) and steady flow (.f##) files used by the plan."))
topic("plan.regime", ("Rezim aliran", "Flow regime"), ("Subkritis dihitung dari hilir ke hulu, superkritis dari hulu ke hilir, campuran memakai keduanya.", "Subcritical is computed from downstream to upstream, supercritical from upstream to downstream, mixed uses both."),
      ("Campuran: De-RAS menghitung profil subkritis lalu profil superkritis. Di tiap penampang dipakai profil dengan gaya spesifik (momentum) lebih besar, sehingga lokasi loncatan hidraulik ketemu. Subkritis butuh batas hilir, superkritis butuh batas hulu, campuran butuh keduanya. Kalau muka air tidak bisa dicari, De-RAS memakai kedalaman kritis dan memberi peringatan.", "Mixed: De-RAS computes the subcritical profile and then the supercritical one. At each section the profile with the larger specific force (momentum) is used, which locates hydraulic jumps. Subcritical needs a downstream boundary, supercritical an upstream one, mixed both. When no water surface can be found, De-RAS uses critical depth and warns."),
      r=("Superkritis dan campuran berstatus Pratinjau: belum dibandingkan dengan HEC-RAS.", "Supercritical and mixed have Preview status: not compared with HEC-RAS yet."), st="preview")
topic("plan.tolerance", ("Toleransi", "Tolerances"), ("Batas selisih muka air hitung–asumsi untuk iterasi standard step dan kedalaman kritis.", "Allowed difference between computed and assumed water surface for standard-step and critical-depth iterations."),
      ("Default 0,003 m (SI) atau 0,01 ft (US).", "Default 0.003 m (SI) or 0.01 ft (US)."))
topic("plan.trials", ("Maksimum iterasi", "Maximum trials"), ("Jumlah iterasi maksimum per penampang (default 20).", "Maximum number of iterations per cross section (default 20)."))
topic("plan.maxerror", ("Toleransi selisih maksimum", "Maximum error tolerance"), ("Bila iterasi tidak konvergen, hasil dengan selisih terkecil diterima jika di bawah nilai ini; bila tidak, dipakai kedalaman kritis.", "If iterations do not converge, the result with the smallest error is accepted when below this value; otherwise critical depth is used."))
topic("plan.friction", ("Metode kemiringan gesek", "Friction slope method"), ("Cara merata-ratakan kemiringan gesek antar dua penampang.", "How the friction slope between two sections is averaged."),
      ("Rata-rata konveyansi (default), rata-rata aritmetik, geometrik atau harmonik, sesuai persamaan di Hydraulic Reference Manual.", "Average conveyance (default), arithmetic, geometric or harmonic mean, per the equations in the Hydraulic Reference Manual."))
topic("sim.doctor", ("Model Doctor", "Model Doctor"), ("Memeriksa data sebelum run (F7): penampang, tebing, n, jarak, debit, kondisi batas, dan plan.", "Checks data before running (F7): sections, banks, n, lengths, discharges, boundaries and plan."),
      ("Kesalahan (⛔) harus diperbaiki sebelum run. Peringatan (⚠) boleh diabaikan asal Anda yakin. Kalau F5 ditekan saat masih ada kesalahan, muncul pop-up yang menyebut tiap kesalahan, lokasinya, dan cara memperbaikinya, kadang dengan tombol perbaikan cepat (misalnya Ganti ke Subkritis).", "Errors (⛔) must be fixed before running. Warnings (⚠) may be ignored if you are sure. If you press F5 while errors remain, a pop-up lists each error, where it is and how to fix it, sometimes with a quick-fix button (for example Switch to Subcritical)."))
topic("sim.run", ("Jalankan plan", "Run plan"), ("Menghitung plan aktif di proses terpisah (F5) dan membuka Jendela Komputasi. Proyek disimpan dulu.", "Computes the current plan in a separate process (F5) and opens the Compute window. The project is saved first."),
      ("Hasil ditulis ke <nama>.<plan>.deras-results.json bersama metadata (versi solver, waktu, hash SHA-256 file masukan) agar bisa direproduksi.", "Results are written to <name>.<plan>.deras-results.json with metadata (solver version, time, SHA-256 of input files) for reproducibility."))
topic("sim.other", ("Mesin lain", "Other engines"), ("Unsteady 1D/2D, quasi-unsteady sedimen, dan kualitas air.", "Unsteady 1D/2D, quasi-unsteady sediment and water quality."), ("1D unsteady tersedia sebagai Pratinjau sejak 0.2.2. Sejak 0.2.3: area 2D, storage area, struktur lateral dan pompa (M6), sedimen quasi-unsteady (M7), kualitas air (M8). Semuanya Pratinjau; lihat Bantuan → Matriks fitur.", "1D unsteady is available as Preview since 0.2.2. Since 0.2.3: 2D areas, storage areas, lateral structures and pumps (M6), quasi-unsteady sediment (M7), water quality (M8). All are Preview; see Help → Feature matrix."), st="preview")

# ---------------- results ----------------
topic("results.view", ("Hasil simulasi", "Simulation results"), ("Tabel, profil memanjang, plot penampang dan pesan run untuk plan aktif.", "Table, longitudinal profile, cross-section plot and run messages for the current plan."),
      ("Baris asal data menyebut solver, versi, dan waktu run. Kalau data berubah setelah run, muncul peringatan bahwa hasil mungkin sudah tidak berlaku. Hasil belum dibandingkan dengan HEC-RAS.", "The origin line names the solver, version and run time. If input files change after the run, a stale-results warning appears. Equivalence with HEC-RAS has not been validated."))
topic("results.xsplot", ("Plot penampang hasil", "Result cross-section plot"), ("Penampang dengan muka air, garis energi dan muka air kritis profil terpilih.", "Cross section with water surface, energy grade and critical WS of the selected profile."))
topic("results.export", ("Ekspor CSV", "Export CSV"), ("Menyimpan tabel hasil semua profil ke CSV (UTF-8, desimal titik).", "Saves the results table of all profiles to CSV (UTF-8, dot decimals)."))
topic("results.report", ("Laporan run (HTML, Word, PDF)", "Run report (HTML, Word, PDF)"), ("Laporan run dwibahasa: metadata, pesan dan tabel hasil, sebagai HTML, Word (.docx) atau PDF.", "A bilingual run report with metadata, messages and the results table, as HTML, Word (.docx) or PDF."),
      ("Klik Laporan… di Hasil dan pilih formatnya. Word dan PDF berisi judul, data run, pesan, dan tabel hasil semua profil (untuk unsteady: profil Max WS). File Word dibuat langsung oleh De-RAS tanpa Microsoft Word dan bisa diedit di Word atau LibreOffice. PDF memakai ukuran A4 mendatar.", "Click Report… in Results and choose the format. Word and PDF contain the title, run data, messages and the results table of all profiles (for unsteady: the Max WS profile). The Word file is written by De-RAS itself, without Microsoft Word, and can be edited in Word or LibreOffice. The PDF uses A4 landscape."),
      st="available", rel=["results.export"])
for k, ti, te, si, se in [
    ("reach", "Reach", "Reach", "Sungai / reach penampang.", "River / reach of the section."),
    ("rs", "RS", "RS", "River Station penampang.", "River Station of the section."),
    ("q", "Q total", "Q total", "Debit total yang mengalir di penampang.", "Total discharge through the section."),
    ("minchel", "Elevasi dasar minimum", "Min Ch El", "Elevasi terendah alur utama.", "Lowest main-channel elevation."),
    ("ws", "Muka air", "W.S. Elev", "Elevasi muka air hasil hitungan.", "Computed water surface elevation."),
    ("critws", "Muka air kritis", "Crit W.S.", "Elevasi muka air pada kedalaman kritis (energi spesifik minimum).", "Water surface at critical depth (minimum specific energy)."),
    ("eg", "Garis energi", "E.G. Elev", "Muka air + αV²/2g.", "Water surface + αV²/2g."),
    ("egslope", "Kemiringan energi", "E.G. Slope", "Kemiringan gesek di penampang, (Q/K)².", "Friction slope at the section, (Q/K)²."),
    ("velch", "Kecepatan alur", "Vel Chnl", "Kecepatan rata-rata di alur utama.", "Mean velocity in the main channel."),
    ("area", "Luas basah", "Flow Area", "Luas aliran total (bantaran + alur).", "Total flow area (overbanks + channel)."),
    ("topwidth", "Lebar muka air", "Top Width", "Lebar permukaan air.", "Width of the water surface."),
    ("froude", "Froude alur", "Froude # Chl", "Bilangan Froude alur utama; < 1 subkritis.", "Main-channel Froude number; < 1 is subcritical."),
    ("qparts", "Pembagian debit", "Flow distribution", "Debit di bantaran kiri, alur dan bantaran kanan menurut konveyansi.", "Discharge in the left overbank, channel and right overbank by conveyance."),
    ("losses", "Kehilangan energi", "Energy losses", "Kehilangan gesek dan kontraksi/ekspansi ke penampang hilir.", "Friction and contraction/expansion losses to the downstream section."),
    ("trials", "Iterasi", "Trials", "Jumlah iterasi standard step di penampang ini.", "Number of standard-step iterations at this section."),
    ("notes", "Catatan", "Notes", "Peringatan perhitungan, misalnya muka air diambil sama dengan kritis atau rasio konveyansi di luar 0,7–1,4.", "Computation warnings, e.g. WS set to critical or conveyance ratio outside 0.7–1.4.")]:
    topic("results.col." + k, (ti, te), (si, se))

