topic("tools.settings", ("Tampilan", "Appearance"), ("Tema, ukuran huruf dan bahasa di view Opsi. Tersimpan untuk pengguna Windows ini.", "Theme, font size and language in the Options view. Stored for this Windows user."))
topic("tools.language", ("Bahasa", "Language"), ("English (bawaan) atau Bahasa Indonesia. Jendela disusun ulang tanpa menutup proyek.", "English (default) or Indonesian. The window is rebuilt without closing the project."))
topic("tools.theme", ("Tema", "Theme"), ("Tema Gelap (bawaan) atau Tema Terang (biru muda), keduanya memakai warna logo De-RAS. Jendela disusun ulang tanpa menutup proyek.", "Dark Theme (default) or Light Theme (light blue), both using the De-RAS logo colours. The window is rebuilt without closing the project."))
topic("tools.fontsize", ("Ukuran huruf", "Font size"), ("Ukuran huruf dasar antarmuka (11–20 px).", "Base interface font size (11–20 px)."))
topic("help.features", ("Matriks fitur", "Feature matrix"), ("Daftar fitur dengan status Selesai, Pratinjau, Parsial atau Belum tersedia, beserta milestone rencananya.", "List of features with status Done, Preview, Partial or Not available, with the planned milestone."))
topic("help.about", ("Tentang De-RAS", "About De-RAS"), ("Versi, pemberitahuan pihak ketiga dan pernyataan bahwa De-RAS tidak berafiliasi dengan HEC.", "Version, third-party notices and the statement that De-RAS is not affiliated with HEC."))

# ---------------- 0.2.0 single-window views (M1) ----------------
topic("view.geometry", ("Data Geometri", "Geometric Data"), ("Skema sungai, palet editor, dan data reach serta penampang (Ctrl+2).", "River schematic, editor palette, and reach and cross-section data (Ctrl+2)."),
      ("Kanvas menampilkan garis tengah reach dan penampang dari file .g##. Palet di kiri membuka editor; fitur yang belum dibuat tampil terkunci dengan milestone rencananya.", "The canvas shows reach centrelines and cross sections from the .g## file. The palette on the left opens editors; features not built yet are shown locked with their planned milestone."),
      (["Pilih file geometri di baris atas.", "Klik objek di kanvas untuk melihat ringkasannya di kartu Objek terpilih.", "Klik ganda penampang untuk membuka Editor Penampang.", "Gunakan Gambar reach untuk menggambar reach baru, atau Tabel… untuk mengedit jarak dan koefisien semua penampang.", "Simpan dengan Ctrl+S."],
       ["Choose the geometry file in the top row.", "Click an object on the canvas to see its summary in the Selected object card.", "Double-click a cross section to open the Cross Section Editor.", "Use Draw reach to draw a new reach, or Tables… to edit lengths and coefficients of all sections.", "Save with Ctrl+S."]),
      rel=["geometry.palette", "geometry.selected", "map.schematic", "view.xs"])
topic("view.xs", ("Editor Penampang", "Cross Section Editor"), ("Sub-view Data Geometri untuk mengedit satu penampang: stasiun–elevasi, tebing, n, jarak dan koefisien.", "Sub-view of Geometric Data for editing one cross section: station–elevation, banks, n, lengths and coefficients."),
      ("Plot menampilkan tanah dan, bila ada hasil, muka air sampai 4 profil. Bila data berubah setelah run, plot memberi catatan hasil usang.", "The plot shows the ground and, when results exist, the water surface for up to 4 profiles. If data changed after the run, the plot notes that the results are stale."),
      rel=["geometry.editor", "geometry.xsdata", "geometry.staelev"])
topic("view.steady", ("Aliran Steady", "Steady Flow"), ("Profil, debit per lokasi dan kondisi batas (file .f##, Ctrl+3).", "Profiles, discharge per location and boundary conditions (.f## file, Ctrl+3)."),
      ("Setiap profil adalah satu skenario debit yang dihitung terpisah. Kondisi batas hulu dan hilir diatur per reach dan profil.", "Each profile is one discharge scenario computed separately. Upstream and downstream boundaries are set per reach and profile."),
      rel=["flow.editor", "flow.boundary", "flow.table"])
topic("view.analysis", ("Analisis Steady", "Steady Analysis"), ("Plan: pilihan geometri dan aliran, rezim, opsi hitung dan Model Doctor (Ctrl+5).", "Plan: geometry and flow selection, regime, computation options and Model Doctor (Ctrl+5)."),
      ("Model Doctor memeriksa ulang setengah detik setelah data berubah. Klik ganda pesan untuk membuka penampang yang disebut. F5 menghitung plan ini.", "Model Doctor refreshes automatically half a second after data changes. Double-click a message to open the cross section it refers to. F5 computes this plan."),
      rel=["plan.editor", "sim.doctor", "sim.run", "plan.output"])
topic("geometry.palette", ("Palet editor", "Editor palette"), ("Tombol menuju editor geometri. Gembok menandai fitur yang belum tersedia.", "Buttons that open the geometry editors. A lock marks features not available yet."),
      ("Reach, Junction, Penampang, Jembatan / Gorong-gorong, Struktur Inline, Struktur Lateral, Storage Area, Area 2D, Sambungan SA/2D, BC line 2D, dan Stasiun Pompa bisa dipakai; selain reach dan penampang semuanya berstatus Pratinjau. Breakline dan wilayah n untuk area 2D belum tersedia di versi ini. Arahkan kursor ke tombol terkunci untuk melihat alasannya.", "Reaches, Junctions, Cross sections, Bridges / Culverts, Inline structures, Lateral structures, Storage areas, 2D areas, SA/2D connections, 2D BC lines and Pump stations work; apart from reaches and cross sections they have Preview status. Breaklines and n regions for 2D areas are not available in this version. Hover a locked button to see why."))
topic("geometry.selected", ("Objek terpilih", "Selected object"), ("Ringkasan reach, penampang atau struktur yang dipilih di kanvas.", "Summary of the reach, cross section or structure selected on the canvas."),
      ("Untuk penampang: jumlah titik, tebing, n, jarak dan koefisien, dengan tombol ke Editor Penampang. Untuk reach: jumlah penampang, panjang alur, koordinat, dan Kelola reach…", "For a cross section: point count, banks, n, lengths and coefficients, with a button to the Cross Section Editor. For a reach: section count, channel length, coordinates, and Manage reaches…"))
topic("geometry.newfile", ("File geometri baru", "New geometry file"), ("Membuat file .g## berikutnya di proyek ini, kosong atau salinan file yang aktif.", "Creates the next .g## file in this project, empty or as a copy of the current file."))
topic("geometry.xsdata", ("Data penampang", "Section data"), ("RS, deskripsi, jarak ke hilir, tebing, n Manning dan koefisien penampang ini.", "RS, description, downstream lengths, banks, Manning's n and coefficients of this section."),
      ("Kalau n berbeda-beda di dalam penampang, pakai Tabel titik n…. Ineffective area, levee, dan obstruction diedit lewat tombolnya masing-masing. n vertikal belum tersedia di versi ini; datanya di file tetap tersimpan.", "When n varies within the section, use n breakpoint table…. Ineffective areas, levees and obstructions are edited with their own buttons. Vertical n is still locked (M8); its data in the file is preserved."),
      rel=["geometry.lengths", "geometry.banks", "geometry.manning", "geometry.coefficients"])
topic("flow.newfile", ("File aliran baru", "New flow file"), ("Membuat file .f## berikutnya, kosong atau salinan file yang aktif.", "Creates the next .f## file, empty or as a copy of the current file."))
topic("flow.col.bcupstream", ("Batas hulu", "Upstream boundary"), ("Kondisi batas di penampang paling hulu reach: normal depth, muka air diketahui, atau kedalaman kritis.", "Boundary at the most upstream section of the reach: normal depth, known water surface or critical depth."),
      ("Hanya dipakai rezim superkritis dan campuran. Ujung reach yang tersambung ke junction tidak butuh batas.", "Only used by the supercritical and mixed regimes. Reach ends at a junction need no boundary."))
topic("plan.output", ("File hasil", "Results file"), ("Tempat hasil run disimpan.", "Where the run results are stored."),
      ("De-RAS menulis hasil ke <nama>.<plan>.deras-results.json (dipakai De-RAS sendiri) dan ke <nama>.<plan>.hdf dengan susunan file hasil HEC-RAS (Results/Steady/Output/...). File .hdf yang dibuat program lain tidak ditimpa; hasil De-RAS lalu ditulis ke <nama>.<plan>.deras.hdf.", "De-RAS writes results to <name>.<plan>.deras-results.json (used by De-RAS itself) and to <name>.<plan>.hdf with the HEC-RAS results layout (Results/Steady/Output/...). A .hdf written by another program is never overwritten; De-RAS then writes <name>.<plan>.deras.hdf."),
      r=("Susunan .hdf berstatus Pratinjau: belum dibuka di HEC-RAS (uji K3).", "The .hdf layout has Preview status: not opened in HEC-RAS yet (test K3)."), st="preview")
topic("home.control", ("Kontrol Proyek", "Project Control"), ("Ringkasan proyek terbuka: file, satuan, plan aktif, file geometri dan aliran.", "Summary of the open project: files, units, current plan, geometry and flow files."),
      ("Klik baris untuk membuka view terkait. Deskripsi proyek bisa diedit dari kartu ini.", "Click a row to open the related view. The project description can be edited from this card."), rel=["home.description"])
topic("home.description", ("Deskripsi proyek", "Project description"), ("Catatan bebas tentang proyek, disimpan di file .prj seperti HEC-RAS.", "Free notes about the project, stored in the .prj file as in HEC-RAS."))
topic("options", ("Opsi", "Options"), ("Tampilan (tema, ukuran huruf, bahasa), satuan dan pengaturan proyek (Ctrl+,).", "Appearance (theme, font size, language), units and project settings (Ctrl+,)."),
      ("Tampilan tersimpan untuk pengguna Windows ini. Pengaturan proyek tersimpan di file pendamping De-RAS dan ikut proyek.", "Appearance is stored for this Windows user. Project settings are stored in the De-RAS sidecar file and travel with the project."),
      rel=["tools.theme", "tools.fontsize", "tools.language", "project.settings"])
topic("project.settings", ("Pengaturan proyek", "Project settings"), ("Sistem koordinat, zona waktu, versi HEC-RAS sasaran dan catatan proyek.", "Coordinate system, time zone, target HEC-RAS version and project notes."),
      ("Disimpan di file pendamping De-RAS (bukan di file HEC-RAS), sehingga file HEC-RAS tidak berubah.", "Stored in the De-RAS sidecar file (not in the HEC-RAS files), so the HEC-RAS files are not changed."),
      rel=["project.crs", "project.timezone", "project.target", "project.notes"])
topic("project.units", ("Satuan proyek", "Project units"), ("SI atau US Customary, ditetapkan saat proyek dibuat dan disimpan di file .prj.", "SI or US Customary, set when the project is created and stored in the .prj file."),
      ("Opsi → Konversi satuan proyek SI ↔ US… (Pratinjau, sejak 0.2.3) membuat salinan proyek di folder yang sama dengan nama baru, lalu mengubah satuan salinan: geometri (stasiun, elevasi, panjang, struktur), aliran steady dan unsteady, toleransi plan, dan data modul De-RAS (bukaan pintu, pompa, breach, sedimen, kualitas air). n Manning, koefisien kontraksi/ekspansi dan konsentrasi tidak berubah. Koefisien pelimpah dikali √0,3048 (atau dibagi). Proyek asli tidak diubah.", "Options → Convert project units SI ↔ US… (Preview, since 0.2.3) copies the project into the same folder under a new name, then converts the copy: geometry (stations, elevations, lengths, structures), steady and unsteady flow, plan tolerances, and the De-RAS module data (gate openings, pumps, breaches, sediment, water quality). Manning's n, contraction/expansion coefficients and concentrations do not change. Weir coefficients are multiplied (or divided) by √0.3048. The original project is not changed."),
      (["Simpan proyek.", "Buka Opsi dan klik Konversi satuan proyek SI ↔ US….", "Terima atau ubah nama salinan.", "Pilih Buka salinan, lalu hitung ulang semua plan."], ["Save the project.", "Open Options and click Convert project units SI ↔ US….", "Accept or change the name of the copy.", "Choose Open the copy, then compute every plan again."]),
      ("Terrain, gambar dan layer GIS tidak dikonversi; satuan elevasinya tetap seperti semula, jadi peta dan area 2D di salinan memakai terrain yang satuannya berbeda sampai terrain diganti. File hasil tidak ikut disalin. Angka di file HEC-RAS dibulatkan ke lebar kolom 8 karakter.", "Terrains, pictures and GIS layers are not converted; their elevation units stay as they were, so maps and 2D areas of the copy use a terrain in other units until it is replaced. Result files are not copied. Numbers in the HEC-RAS files are rounded to the 8-character column width."),
      st="preview")
topic("project.crs", ("Sistem koordinat", "Coordinate system"), ("Kode EPSG atau WKT proyek. Dipakai RAS Mapper.", "The project's EPSG code or WKT. Used by RAS Mapper."),
      ("Nilai ini sama dengan yang diatur di RAS Mapper → Atur proyeksi…; mengubah salah satunya mengubah keduanya. RAS Mapper memakainya untuk memeriksa apakah terrain berada di sistem koordinat yang sama. Reproyeksi belum tersedia.", "This is the same value as RAS Mapper → Set projection…; changing either one changes both. RAS Mapper uses it to check that terrains are in the same coordinate system. Reprojection is not available yet."), rel=["mapper.crs"])
topic("project.timezone", ("Zona waktu", "Time zone"), ("Zona waktu proyek, mis. UTC+07:00 (WIB). Analisis Unsteady memakai tanggal dan jam di plan apa adanya, tanpa konversi zona waktu.", "Project time zone, e.g. UTC+07:00 (WIB). Unsteady Analysis uses the plan dates and times as entered, without time zone conversion."), st="partial")
topic("project.target", ("Versi HEC-RAS sasaran", "Target HEC-RAS version"), ("Versi format file HEC-RAS yang ditulis De-RAS. Saat ini hanya 7.00.", "The HEC-RAS file format version De-RAS writes. Currently 7.00 only."))
topic("project.notes", ("Catatan proyek", "Project notes"), ("Catatan internal De-RAS untuk proyek ini (tidak ditulis ke file HEC-RAS).", "De-RAS internal notes for this project (not written to the HEC-RAS files)."))
topic("messages.drawer", ("Panel Pesan", "Messages drawer"), ("Log aktivitas dan daftar temuan Model Doctor (Ctrl+M).", "Activity log and the Model Doctor findings (Ctrl+M)."),
      ("Jumlah kesalahan dan peringatan di bilah status selalu terbaru. Klik ganda pesan untuk membuka lokasinya.", "The error and warning counts in the status bar are always current. Double-click a finding to open its location."), rel=["sim.doctor"])
topic("compute.window", ("Jendela Komputasi", "Compute window"), ("Jendela terpisah yang menampilkan langkah, kemajuan, antrean dan log run (F5).", "A separate window showing the steps, progress, queue and log of a run (F5)."),
      ("Jendela utama tetap bisa dipakai selama run. Menutup jendela saat run berjalan menanyakan apakah run dibatalkan atau tetap jalan di latar.", "The main window stays usable during a run. Closing the window during a run asks whether to cancel the run or keep it running in the background."),
      rel=["compute.steps", "compute.queue", "compute.log", "sim.run"])
topic("compute.steps", ("Langkah komputasi", "Compute steps"), ("Persiapan geometri, simulasi steady, dan penulisan hasil. Peta genangan dibuat sesudahnya di RAS Mapper.", "Geometry preprocessing, steady simulation, writing results. The inundation map is made afterwards in RAS Mapper."), rel=["mapper.inundation"])
topic("compute.queue", ("Antrean run", "Run queue"), ("Plan yang menunggu dihitung; dijalankan satu per satu.", "Plans waiting to be computed; they run one at a time."))
topic("compute.log", ("Log run", "Run log"), ("Pesan mesin hitung selama run. Batalkan menghentikan mesin dengan aman. Kalau run dibatalkan atau gagal, hasil lama tidak berubah.", "Engine messages during the run. Cancel stops the engine safely; previous results are unchanged when a run is cancelled or fails."))
topic("results.xs", ("Hasil: penampang", "Results: cross section"), ("Penampang dengan muka air, garis energi dan muka air kritis untuk profil terpilih.", "Cross section with water surface, energy grade and critical WS for the chosen profile."), rel=["results.view"])
topic("results.profile", ("Hasil: profil memanjang", "Results: profile"), ("Dasar saluran, muka air dan garis energi sepanjang reach.", "Channel invert, water surface and energy grade along the reach."), rel=["results.view"])
topic("results.rating", ("Hasil: kurva rating", "Results: rating curve"), ("Muka air, garis energi, dan muka air kritis terhadap debit di satu penampang, dari semua profil plan.", "Water surface, energy grade and critical WS against flow at one cross section, from all profiles of the plan."),
      ("Makin banyak profil, makin halus kurvanya. Titik di antara profil adalah garis lurus, bukan hasil hitungan.", "More profiles give a smoother curve. Between profiles the line is straight, not computed."), rel=["results.view"])
topic("results.general", ("Hasil: plot umum", "Results: general plot"), ("Satu variabel hasil (mis. kecepatan, Froude) terhadap jarak sepanjang reach.", "One result variable (e.g. velocity, Froude) against distance along the reach."), rel=["results.view"])
topic("results.detail", ("Hasil: tabel rinci", "Results: detailed table"), ("Semua besaran hasil di satu penampang untuk profil terpilih: bantaran kiri, alur dan bantaran kanan.", "All result quantities at one cross section for the chosen profile: left overbank, channel and right overbank."), rel=["results.view"])
topic("results.table", ("Hasil: tabel profil", "Results: profile table"), ("Tabel hasil semua penampang dan profil; bisa diekspor ke CSV.", "Results table for all sections and profiles; can be exported to CSV."), rel=["results.export"])
topic("results.messages", ("Hasil: pesan run", "Results: run messages"), ("Peringatan dan catatan perhitungan dari run terakhir, per penampang.", "Warnings and computation notes from the last run, per cross section."), rel=["results.view"])

# ---------------- RAS Mapper (M3) ----------------
PV = ("Status Pratinjau: belum dibandingkan dengan RAS Mapper HEC-RAS.", "Preview status: not compared with HEC-RAS RAS Mapper yet.")
topic("view.mapper", ("RAS Mapper", "RAS Mapper"), ("Peta proyek: terrain, gambar latar, garis tengah reach, garis potong penampang, dan peta genangan (Ctrl+6).", "The project map: terrain, background pictures, reach centrelines, cross-section cut lines and inundation maps (Ctrl+6)."),
      ("Seret untuk menggeser peta, roda mouse untuk zoom, Home atau Pas layar untuk menampilkan semuanya. Klik garis potong untuk memilih penampangnya. Garis potong putus-putus berarti penampang itu belum punya garis potong di file; De-RAS meletakkannya tegak lurus garis tengah menurut panjang ruas.", "Drag to pan, mouse wheel to zoom, Home or Fit to show everything. Click a cut line to select its cross section. A dashed cut line means the section has no cut line in the file; De-RAS places it across the centreline using the reach lengths."),
      r=PV, st="preview", rel=["mapper.terrain", "mapper.cut", "mapper.inundation", "mapper.crs"])
topic("mapper.layers", ("Lapisan peta", "Map layers"), ("Proyeksi, terrain, gambar latar, geometri, dan peta genangan, dari bawah ke atas.", "Projection, terrains, background pictures, geometry and inundation map, from bottom to top."),
      ("Daftar terrain dan gambar latar disimpan di file De-RAS proyek (.deras.json). File HEC-RAS tidak diubah.", "The terrain and picture lists are stored in the De-RAS project file (.deras.json). HEC-RAS files are not changed."))
topic("mapper.crs", ("Proyeksi (CRS)", "Projection (CRS)"), ("Sistem koordinat peta proyek: kode EPSG atau teks WKT dari file .prj ESRI.", "The project's map coordinate system: an EPSG code or the WKT text of an ESRI .prj file."),
      ("De-RAS belum memproyeksi ulang data. Terrain, gambar latar, garis tengah, dan garis potong harus memakai sistem koordinat yang sama. Kalau EPSG terrain berbeda dengan proyeksi proyek, De-RAS memberi peringatan. Proyeksi dari RAS Mapper HEC-RAS (.rasmap) ditampilkan bila ada.", "De-RAS does not reproject data yet. Terrains, pictures, centrelines and cut lines must use the same coordinate system. De-RAS warns when a terrain's EPSG differs from the project projection. The projection of HEC-RAS RAS Mapper (.rasmap) is shown when present."),
      (["Buka RAS Mapper (Ctrl+6).", "Klik Atur proyeksi….", "Ketik kode EPSG, atau klik Dari file .prj… atau Dari terrain.", "Klik Terapkan, lalu simpan proyek."],
       ["Open RAS Mapper (Ctrl+6).", "Click Set projection….", "Type an EPSG code, or click From .prj file… or From terrain.", "Click Apply, then save the project."]), st="preview")
topic("mapper.terrain", ("Terrain", "Terrain"), ("Model elevasi (DEM) dalam GeoTIFF satu band.", "An elevation model (DEM) as a single-band GeoTIFF."),
      ("De-RAS membaca GeoTIFF tanpa kompresi, LZW, atau Deflate, dalam bentuk strip atau tile, nilai bulat atau desimal. BigTIFF dan raster yang diputar belum didukung. File di luar folder proyek disalin ke folder Terrain proyek. Terrain RAS Mapper HEC-RAS (.hdf) tidak dibaca langsung, tetapi GeoTIFF sumbernya di folder yang sama ikut dimuat. Kalau beberapa terrain bertumpuk, yang paling atas di daftar dipakai.", "De-RAS reads GeoTIFFs without compression, LZW or Deflate, as strips or tiles, with integer or floating-point values. BigTIFF and rotated rasters are not supported yet. Files outside the project folder are copied to the project's Terrain folder. HEC-RAS RAS Mapper terrains (.hdf) are not read directly, but their source GeoTIFFs in the same folder are loaded. Where terrains overlap, the first one in the list is used."),
      (["Klik Tambah GeoTIFF… di kartu Terrain.", "Pilih file .tif.", "Simpan proyek agar terrain tercatat."], ["Click Add GeoTIFF… on the Terrain card.", "Choose the .tif file.", "Save the project so the terrain is recorded."]),
      ("Daftar terrain di .deras.json; file GeoTIFF di folder Terrain.", "Terrain list in .deras.json; GeoTIFF files in the Terrain folder."), st="preview")
topic("mapper.picture", ("Gambar latar", "Background pictures"), ("Foto udara atau peta (PNG, JPG, BMP) dengan world file.", "Aerial photos or maps (PNG, JPG, BMP) with a world file."),
      ("World file berisi enam angka yang menaruh gambar di peta (mis. foto.pgw untuk foto.png, foto.jgw untuk foto.jpg). Gambar yang diputar belum didukung. Gambar tidak disalin; hanya lokasinya yang dicatat.", "A world file holds six numbers that place the picture on the map (e.g. photo.pgw for photo.png, photo.jgw for photo.jpg). Rotated pictures are not supported yet. Pictures are not copied; only their location is recorded."), st="preview")
topic("mapper.geometry", ("Geometri di peta", "Geometry on the map"), ("Garis tengah reach (biru, panah ke hilir) dan garis potong penampang (kuning).", "Reach centrelines (blue, arrow pointing downstream) and cross-section cut lines (yellow)."),
      ("Garis potong dari file (XS GIS Cut Line) digambar utuh. Penampang tanpa garis potong digambar putus-putus, tegak lurus garis tengah dan berjarak sesuai panjang ruas alur utama.", "Cut lines from the file (XS GIS Cut Line) are solid. Sections without one are dashed, across the centreline and spaced by the main-channel lengths."))
topic("mapper.cut", ("Potong penampang dari terrain", "Cut cross sections from the terrain"), ("Membuat penampang baru dari garis yang digambar di atas terrain, atau memperbarui penampang terpilih.", "Creates a new cross section from a line drawn on the terrain, or updates the selected one."),
      ("Titik stasiun-elevasi diambil setiap jarak sampel (bawaan: ukuran sel terrain), lalu titik yang segaris dibuang sampai paling banyak 500 titik. Tebing, n Manning, dan koefisien disalin dari penampang tetangga dan digeser ke titik terdekat. Panjang ruas penampang hulu dibagi dua menurut posisi garis. Garis yang digambar dari kanan ke kiri dibalik otomatis.", "Station-elevation points are sampled every sample spacing (default: the terrain cell size), then points on a straight line are dropped until at most 500 remain. Bank stations, Manning's n and coefficients are copied from the neighbouring section and moved to the nearest points. The upstream section's reach lengths are split by the position of the line. A line drawn right to left is reversed automatically."),
      (["Klik Potong penampang.", "Klik titik-titik garis dari tebing kiri ke kanan (menghadap hilir), memotong garis tengah reach.", "Klik ganda atau Enter untuk selesai.", "Periksa RS usulan, klik Buat penampang.", "Periksa tebing dan n di Editor Penampang, lalu simpan geometri."],
       ["Click Cut cross section.", "Click the line points from the left to the right bank (looking downstream), crossing the reach centreline.", "Double-click or press Enter to finish.", "Check the proposed RS, click Create section.", "Check banks and n in the Cross-Section Editor, then save the geometry."]),
      ("Baris XS GIS Cut Line= di file .g##.", "The XS GIS Cut Line= line of the .g## file."), PV, st="preview")
topic("mapper.inundation", ("Peta genangan", "Inundation map"), ("Kedalaman dan muka air satu profil steady di atas terrain.", "Depth and water surface of one steady profile over the terrain."),
      ("Di antara dua garis potong yang berurutan, muka air diinterpolasi linear menurut jarak ke kedua garis. Kedalaman = muka air - terrain, hanya yang positif. Grid mengikuti terrain pertama. Belum ada cek keterhubungan aliran, jadi cekungan terpisah di dalam batas garis potong ikut tergenang.", "Between two consecutive cut lines the water surface is interpolated linearly by the distances to both lines. Depth = water surface - terrain, positive values only. The grid follows the first terrain. There is no flow connectivity check yet, so separate depressions inside the cut lines are flooded too."),
      (["Jalankan plan (F5).", "Di RAS Mapper pilih profil di kartu Peta genangan.", "Klik Hitung peta."], ["Run the plan (F5).", "In RAS Mapper pick a profile on the Inundation map card.", "Click Compute map."]),
      r=PV, st="preview", rel=["mapper.export"])
topic("mapper.export", ("Ekspor peta", "Map export"), ("Kedalaman atau muka air sebagai GeoTIFF, atau gambar peta sebagai PNG.", "Depth or water surface as GeoTIFF, or the map picture as PNG."),
      ("GeoTIFF ditulis float32 tanpa kompresi dengan no data -9999 dan sistem koordinat terrain, sehingga bisa dibuka di QGIS atau ArcGIS.", "GeoTIFFs are float32, uncompressed, no data -9999, with the terrain's coordinate system, so they open in QGIS or ArcGIS."))
topic("results.3d", ("Hasil: perspektif 3D", "Results: 3D perspective"), ("Penampang satu reach dan muka air satu profil dalam tampilan tiga dimensi.", "The cross sections of one reach and the water surface of one profile in a three-dimensional view."),
      ("Penampang diletakkan menurut panjang ruas alur utama, berpusat di tengah alur. Seret untuk memutar, roda mouse untuk mengubah skala vertikal.", "Sections are placed by the main-channel lengths, centred on the channel. Drag to rotate, mouse wheel to change the vertical exaggeration."))

# ---------------- unsteady (M5, preview) ----------------
UV = ("Status Pratinjau: hasil belum dibandingkan dengan HEC-RAS. Hanya rezim subkritis, satu alur per reach. Struktur lateral, storage area, area 2D, sambungan, dan pompa dihitung sejak 0.2.3 (juga Pratinjau); jembatan, gorong-gorong, dan struktur inline belum dihitung di unsteady.", "Preview status: results are not compared with HEC-RAS yet. Subcritical only, one flow path per reach. Lateral structures, storage areas, 2D areas, connections and pumps are computed since 0.2.3 (also Preview); bridges, culverts and inline structures are not computed in unsteady runs yet.")
topic("view.unsteady", ("Data Aliran Unsteady", "Unsteady Flow Data"), ("Kondisi batas yang berubah terhadap waktu dan debit awal (file .u##, Ctrl+4).", "Time-varying boundary conditions and initial flows (.u## file, Ctrl+4)."),
      ("Kiri: daftar lokasi kondisi batas. Kanan: data lokasi terpilih (jenis, interval, tabel nilai dan grafik). Di bawah daftar: debit awal per reach.", "Left: the list of boundary locations. Right: the data of the selected location (type, interval, value table and plot). Below the list: initial flows per reach."),
      (["Pilih file aliran unsteady di atas daftar, atau buat baru dengan tombol +.", "Klik Lengkapi ujung reach. Ujung hulu mendapat hidrograf debit, ujung hilir normal depth.", "Pilih tiap lokasi dan isi datanya.", "Isi debit awal setiap reach.", "Simpan proyek, lalu buka Analisis Unsteady."],
       ["Pick the unsteady flow file above the list, or create one with the + button.", "Click Add reach ends. Upstream ends get a flow hydrograph, downstream ends normal depth.", "Select each location and enter its data.", "Enter the initial flow of every reach.", "Save the project, then open Unsteady Analysis."]),
      ("File .u## (Boundary Location, Interval, Flow Hydrograph, Stage Hydrograph, Friction Slope, Initial Flow Loc).", "The .u## file (Boundary Location, Interval, Flow Hydrograph, Stage Hydrograph, Friction Slope, Initial Flow Loc lines)."),
      UV, st="preview", rel=["unsteady.boundaries", "unsteady.initial", "unsteady.data", "view.run-unsteady"])
topic("unsteady.boundaries", ("Lokasi kondisi batas", "Boundary condition locations"), ("Setiap ujung hulu dan hilir reach yang tidak tersambung ke junction butuh satu kondisi batas.", "Every upstream and downstream reach end not connected to a junction needs one boundary condition."),
      ("Lengkapi ujung reach menambahkan lokasi yang belum ada. Aliran lateral… menambah debit masuk di tengah reach. Hapus membuang lokasi terpilih. Model Doctor memberi kesalahan bila ada ujung reach tanpa kondisi batas atau dengan jenis yang tidak cocok (mis. normal depth di hulu).", "Add reach ends adds the missing locations. Lateral inflow… adds an inflow inside a reach. Delete removes the selected location. Model Doctor reports an error when a reach end has no boundary condition or an unsuitable type (e.g. normal depth upstream)."),
      st="preview", rel=["unsteady.types", "unsteady.lateral"])
topic("unsteady.initial", ("Debit awal", "Initial flows"), ("Debit di setiap reach pada awal simulasi.", "The flow in every reach at the start of the simulation."),
      ("De-RAS menghitung profil steady (backwater subkritis) dengan debit ini dan kondisi batas hilir pada jam pertama, lalu memakainya sebagai keadaan awal. Kosong berarti nilai pertama hidrograf hulu dipakai.", "De-RAS computes a steady (subcritical backwater) profile with these flows and the downstream boundary at the first hour, and uses it as the initial state. Empty means the first value of the upstream hydrograph is used."),
      st="preview", rel=["view.unsteady"])
topic("unsteady.data", ("Data kondisi batas", "Boundary condition data"), ("Jenis, interval, dan nilai kondisi batas pada lokasi terpilih.", "Type, interval and values of the boundary condition at the selected location."),
      ("Tabel dan grafik menyesuaikan jenis: hidrograf (nilai per interval), normal depth (kemiringan gesek), atau rating curve (pasangan elevasi–debit).", "The table and plot follow the type: hydrograph (one value per interval), normal depth (friction slope) or rating curve (stage–flow pairs)."),
      st="preview", rel=["unsteady.types", "unsteady.interval", "unsteady.hydrograph", "unsteady.normal", "unsteady.rating"])
topic("unsteady.types", ("Jenis kondisi batas", "Boundary condition types"), ("Hidrograf debit, hidrograf muka air, aliran lateral, aliran lateral merata, normal depth, dan rating curve.", "Flow hydrograph, stage hydrograph, lateral inflow, uniform lateral inflow, normal depth and rating curve."),
      ("Hulu: hidrograf debit atau muka air. Hilir: hidrograf muka air, normal depth, rating curve, atau hidrograf debit. Di tengah reach: aliran lateral (satu titik) atau aliran lateral merata (dibagi rata menurut panjang antara dua RS). Jenis lain (mis. gate opening, IB stage/flow) tetap disimpan di file tetapi belum dihitung.", "Upstream: flow or stage hydrograph. Downstream: stage hydrograph, normal depth, rating curve or flow hydrograph. Inside a reach: lateral inflow (one point) or uniform lateral inflow (spread by length between two RS). Other types (e.g. gate openings, IB stage/flow) stay in the file but are not computed yet."),
      st="preview")
topic("unsteady.interval", ("Interval", "Intervals"), ("Jarak waktu antara dua nilai data, langkah hitung, atau keluaran: 1MIN sampai 1DAY.", "The time between two data values, computation steps or outputs: 1MIN to 1DAY."),
      ("Interval data hidrograf tidak harus sama dengan interval komputasi; nilai di antaranya diinterpolasi linear. Interval keluaran sebaiknya kelipatan interval komputasi. Hasil disimpan paling banyak 100 waktu keluaran.", "The hydrograph data interval need not match the computation interval; values in between are interpolated linearly. The output interval should be a multiple of the computation interval. At most 100 output times are stored."),
      st="preview")
topic("unsteady.hydrograph", ("Hidrograf", "Hydrograph"), ("Deret nilai debit atau muka air, satu per interval data, mulai dari waktu mulai simulasi.", "A series of flow or stage values, one per data interval, starting at the simulation start time."),
      ("Ketik atau tempel nilai di tabel; grafik di samping ikut berubah. Kalau simulasi lebih panjang dari hidrograf, nilai terakhir dipakai terus dan Model Doctor memberi peringatan.", "Type or paste values into the table; the plot alongside updates. If the simulation is longer than the hydrograph, the last value is held and Model Doctor warns."),
      st="preview")
topic("unsteady.normal", ("Normal depth", "Normal depth"), ("Debit hilir dari persamaan Manning dengan kemiringan gesek yang diisi.", "The downstream flow from Manning's equation with the given friction slope."),
      ("Di setiap langkah, debit di ujung hilir dihitung dari muka air saat itu: Q = K·√S. Kemiringan harus lebih dari 0.", "At every step the downstream flow is computed from the current water surface: Q = K·√S. The slope must be greater than 0."),
      st="preview")
topic("unsteady.rating", ("Rating curve", "Rating curve"), ("Hubungan elevasi–debit di ujung hilir.", "A stage–flow relation at the downstream end."),
      ("Isi pasangan elevasi dan debit yang naik. Di antara titik dipakai interpolasi linear. Format baris Rating Curve di file .u## belum diverifikasi dengan HEC-RAS.", "Enter increasing stage and flow pairs. Linear interpolation is used between points. The Rating Curve line format of the .u## file is not verified against HEC-RAS yet."),
      st="preview")
topic("unsteady.lateral", ("Aliran lateral", "Lateral inflow"), ("Debit masuk di tengah reach, di satu penampang atau merata di antara dua penampang.", "Inflow inside a reach, at one cross section or spread between two cross sections."),
      steps=(["Klik Aliran lateral….", "Pilih reach, jenis, dan RS masuk (dan RS akhir untuk aliran merata).", "Klik Tambah, lalu isi hidrografnya."], ["Click Lateral inflow….", "Pick the reach, the type and the inflow RS (and the end RS for uniform inflow).", "Click Add, then fill its hydrograph."]),
      st="preview")
topic("view.run-unsteady", ("Analisis Unsteady", "Unsteady Flow Analysis"), ("Plan unsteady: file geometri dan aliran, waktu simulasi, interval, opsi, dan Model Doctor.", "Unsteady plan: geometry and flow files, simulation window, intervals, options and Model Doctor."),
      ("Metode: skema implisit Preissmann empat titik pada persamaan Saint-Venant, iterasi Newton per langkah. Keadaan awal dari profil steady. Junction memakai muka air sama dan kontinuitas. Model Doctor menolak run bila geometri berisi jembatan, gorong-gorong, atau struktur inline.", "Method: the four-point Preissmann implicit scheme on the Saint-Venant equations, Newton iterations per step. The initial state comes from a steady profile. Junctions use equal stage and continuity. Model Doctor refuses the run when the geometry contains bridges, culverts or inline structures."),
      (["Pilih plan unsteady, atau klik + untuk membuat plan baru.", "Pilih file geometri dan file aliran unsteady.", "Isi tanggal dan jam mulai dan selesai (mis. 01JAN2024, 0000).", "Pilih interval komputasi dan keluaran.", "Tekan F7 untuk Model Doctor, lalu F5 untuk menghitung."],
       ["Pick an unsteady plan, or click + to create one.", "Pick the geometry file and the unsteady flow file.", "Enter the start and end dates and times (e.g. 01JAN2024, 0000).", "Choose the computation and output intervals.", "Press F7 for Model Doctor, then F5 to compute."]),
      ("Baris Simulation Date, Computation Interval, Output Interval, UNET Theta, UNET ZTol, dan UNET MaxIter di file .p##.", "Simulation Date, Computation Interval, Output Interval, UNET Theta, UNET ZTol and UNET MaxIter lines in the .p## file."),
      ("Hasil ditulis ke <nama>.<plan>.deras-results.json: profil Max WS, profil setiap waktu keluaran, dan time series muka air dan debit di semua penampang. File .hdf hasil unsteady belum ditulis. " + UV[0], "Results go to <name>.<plan>.deras-results.json: a Max WS profile, a profile for every output time, and stage and flow time series at every section. No unsteady .hdf results file is written yet. " + UV[1]),
      st="preview", rel=["unsteady.time", "unsteady.interval", "unsteady.theta", "results.hydrograph"])
topic("unsteady.time", ("Waktu simulasi", "Simulation window"), ("Tanggal dan jam mulai dan selesai simulasi.", "Start and end date and time of the simulation."),
      ("Tanggal ditulis DDMMMYYYY (mis. 01JAN2024), jam HHMM (mis. 0000 atau 2400). Selesai harus setelah mulai. Hidrograf dimulai pada waktu mulai.", "Dates are written DDMMMYYYY (e.g. 01JAN2024), times HHMM (e.g. 0000 or 2400). The end must be after the start. Hydrographs start at the start time."),
      st="preview")
topic("unsteady.theta", ("Theta dan toleransi", "Theta and tolerances"), ("Bobot implisit (0,5–1,0), toleransi muka air, dan iterasi maksimum per langkah.", "Implicit weighting (0.5–1.0), water surface tolerance and maximum iterations per step."),
      ("Theta 1,0 paling stabil; nilai mendekati 0,6 lebih akurat tetapi bisa berosilasi. Iterasi Newton berhenti bila perubahan muka air di bawah toleransi. Bila iterasi maksimum tercapai, langkah tetap diterima dan dicatat sebagai peringatan.", "Theta 1.0 is the most stable; values near 0.6 are more accurate but can oscillate. Newton iterations stop when the water surface change is below the tolerance. When the maximum is reached the step is still accepted and logged as a warning."),
      st="preview")
topic("results.hydrograph", ("Hasil: hidrograf", "Results: hydrographs"), ("Muka air dan debit terhadap waktu di satu penampang, dari hasil plan unsteady.", "Stage and flow against time at one cross section, from an unsteady plan result."),
      ("Pilih reach dan penampang. Grafik atas: muka air dengan garis dasar alur. Grafik bawah: debit. " + UV[0], "Pick the reach and section. Top plot: stage with the channel invert line. Bottom plot: flow. " + UV[1]), st="preview", rel=["results.timeseries"])
topic("results.timeseries", ("Hasil: time series", "Results: time series"), ("Tabel tanggal, jam, muka air, dan debit di satu penampang setiap waktu keluaran.", "A table of date, hour, stage and flow at one cross section for every output time."),
      ("Tabel bisa disalin ke spreadsheet. " + UV[0], "The table can be copied into a spreadsheet. " + UV[1]), st="preview", rel=["results.hydrograph"])

# ---------------- M6 (0.2.3): storage areas, 2D areas, lateral structures, pumps ----------------
M6 = ("Status Pratinjau: dihitung oleh Analisis Unsteady, hasil belum dibandingkan dengan HEC-RAS.", "Preview status: computed by Unsteady Flow Analysis; results are not compared with HEC-RAS yet.")
topic("geometry.lateral", ("Struktur lateral", "Lateral structure"), ("Pelimpah atau tanggul di sisi reach yang mengalirkan air ke storage area, area 2D, atau keluar sistem.", "A weir or levee along a reach that spills water into a storage area, a 2D area or out of the system."),
      ("Aliran dihitung dengan persamaan pelimpah Q = C·L·H^1,5 per potongan mercu, dengan reduksi tenggelam Villemonte bila muka air hilir naik. Aliran bisa berbalik bila area lebih tinggi dari sungai. Koefisien default 1,1 (SI) atau 2,0 (US). Struktur lateral hanya dihitung di plan unsteady; plan steady mengabaikannya dengan peringatan.", "Flow uses the weir equation Q = C·L·H^1.5 per crest piece, with Villemonte submergence when the tailwater rises. Flow reverses when the area is higher than the river. Default coefficient 1.1 (SI) or 2.0 (US). Lateral structures are computed in unsteady plans only; steady plans skip them with a warning."),
      (["Di Data Geometri, pilih reach, lalu klik Struktur Lateral di palet.", "Klik Tambah, isi RS (di antara dua penampang), sisi (kiri atau kanan menghadap hilir), dan jarak dari penampang hulu.", "Pilih tujuan: keluar sistem, storage area, atau area 2D.", "Isi tabel stasiun–elevasi mercu dan koefisien pelimpah.", "Bila perlu, isi data keruntuhan (breach) dan klik Perkiraan Froehlich untuk usulan lebar dan waktu runtuh."],
       ["In Geometric Data, select the reach, then click Lateral Structure in the palette.", "Click Add, enter the RS (between two cross sections), the side (left or right looking downstream) and the distance from the upstream section.", "Pick the destination: out of the system, a storage area or a 2D area.", "Fill the crest station–elevation table and the weir coefficient.", "If needed, fill the breach data and click Froehlich estimate for a suggested width and formation time."]),
      ("Blok Lateral Weir di file .g## (Type 6). Data breach disimpan di file .deras.json proyek karena HEC-RAS menyimpannya di plan.", "Lateral Weir lines in the .g## file (Type 6). Breach data is stored in the project's .deras.json, because HEC-RAS keeps it in the plan file."),
      ("Hidrograf debit lateral tampil di Hasil (pilih \"Struktur lateral: …\" di daftar reach). " + M6[0], "The lateral flow hydrograph appears in Results (pick \"Lateral structure: …\" in the reach list). " + M6[1]),
      st="preview", rel=["geometry.storage", "geometry.area2d", "geometry.col.weir", "unsteady.area"])
topic("geometry.storage", ("Storage area", "Storage area"), ("Kolam atau dataran yang menampung air dengan satu muka air datar.", "A pond or floodplain that stores water at one level water surface."),
      ("Volume dari tabel elevasi–volume, dari luas datar di atas elevasi minimum, atau dari terrain di dalam poligon. Muka air semua storage area yang terhubung dihitung bersama dengan Newton di setiap langkah.", "Volume comes from an elevation–volume table, from a flat area above a minimum elevation, or from the terrain inside the polygon. The water surfaces of all connected storage areas are solved together with Newton iterations at every step."),
      (["Klik Storage Area di palet, lalu gambar poligon di kanvas (klik titik-titik, klik ganda untuk selesai), atau klik Tambah di daftar.", "Beri nama dan pilih cara menghitung volume.", "Isi tabel elevasi–volume atau luas dan elevasi minimum, atau pilih Terrain.", "Hubungkan dengan struktur lateral, sambungan SA/2D, atau pompa."],
       ["Click Storage Area in the palette, then draw the polygon on the canvas (click the points, double-click to finish), or click Add in the list.", "Give it a name and choose how the volume is computed.", "Fill the elevation–volume table, or the area and minimum elevation, or choose Terrain.", "Connect it with a lateral structure, an SA/2D connection or a pump."]),
      ("Blok Storage Area di file .g##.", "Storage Area block in the .g## file."),
      ("Muka air dan volume storage area tampil di Hasil. " + M6[0], "The storage area stage appears in Results. " + M6[1]), st="preview", rel=["geometry.col.volume", "geometry.connection", "unsteady.area"])
topic("geometry.area2d", ("Area aliran 2D", "2D flow area"), ("Wilayah dataran yang alirannya dihitung 2D di atas grid sel persegi.", "A floodplain region where flow is computed in 2D on a grid of square cells."),
      ("Metode: persamaan gelombang difusi, implisit penuh, di grid persegi di dalam poligon. Setiap sel menyimpan sampel terrain (subgrid), sehingga volume sel dan konveyansi muka sel mengikuti bentuk terrain di dalam sel. Ini berbeda dari mesh poligon HEC-RAS; hasilnya belum dibandingkan. Area 2D membutuhkan terrain di RAS Mapper.", "Method: diffusion-wave equations, fully implicit, on a square grid inside the polygon. Every cell keeps its terrain samples (subgrid), so the cell volume and the face conveyance follow the terrain inside the cell. This differs from the HEC-RAS polygon mesh; results are not compared yet. A 2D area needs a terrain in RAS Mapper."),
      (["Pastikan terrain sudah ditambahkan di RAS Mapper.", "Klik Area 2D di palet, lalu gambar poligon di kanvas.", "Isi nama, ukuran sel (kosong = sekitar 1/60 sisi terpanjang), dan n Manning.", "Tambahkan BC line di tepi area bila air harus masuk atau keluar lewat tepi itu."],
       ["Make sure a terrain is added in RAS Mapper.", "Click 2D Area in the palette, then draw the polygon on the canvas.", "Enter the name, the cell size (empty = about 1/60 of the longest side) and Manning's n.", "Add a BC line on the area edge where water must enter or leave."]),
      ("Blok Storage Area dengan Storage Area Is2D=-1 di file .g##; ukuran sel di baris Point Generation Data.", "Storage Area block with Storage Area Is2D=-1 in the .g## file; the cell size goes on the Point Generation Data line."),
      ("Kedalaman maksimum, kedalaman per waktu, kecepatan maksimum, dan waktu tiba tampil di RAS Mapper → Hasil area 2D. Selisih volume ditulis di pesan run. " + M6[0], "Maximum depth, depth per time, maximum velocity and arrival time appear in RAS Mapper → 2D area results. The volume error is written in the run messages. " + M6[1]),
      st="preview", rel=["geometry.bcline", "mapper.results2d", "mapper.terrain", "unsteady.area"])
topic("geometry.connection", ("Sambungan SA/2D", "SA/2D connection"), ("Pelimpah antara dua storage area atau area 2D.", "A weir between two storage areas or 2D areas."),
      ("Aliran dengan persamaan pelimpah yang sama dengan struktur lateral, dua arah. Data breach bisa diisi seperti di struktur lateral.", "Flow uses the same weir equation as lateral structures, in both directions. Breach data can be entered as for lateral structures."),
      (["Klik Sambungan di palet, lalu gambar garisnya di kanvas.", "Pilih area hulu dan hilir.", "Isi tabel mercu, lebar, dan koefisien."], ["Click Connection in the palette, then draw its line on the canvas.", "Pick the upstream and downstream areas.", "Fill the crest table, width and coefficient."]),
      ("Blok Connection di file .g##.", "Connection block in the .g## file."), M6, st="preview", rel=["geometry.storage", "geometry.area2d", "geometry.col.weir"])
topic("geometry.bcline", ("BC line area 2D", "2D area BC line"), ("Garis di tepi area 2D tempat kondisi batas dipasang.", "A line on the edge of a 2D area where a boundary condition is applied."),
      ("Sel yang dipotong garis menerima kondisi batasnya: hidrograf debit (dibagi menurut konveyansi), hidrograf muka air, atau normal depth (keluar dengan kemiringan gesek yang diisi).", "The cells crossed by the line receive its boundary condition: a flow hydrograph (shared by conveyance), a stage hydrograph or normal depth (outflow with the given friction slope)."),
      (["Klik BC Line di palet, lalu gambar garis di dekat tepi area 2D.", "Pilih area 2D dan beri nama.", "Di Data Aliran Unsteady, klik Area/BC line… untuk memasang kondisi batasnya."], ["Click BC Line in the palette, then draw the line near the edge of the 2D area.", "Pick the 2D area and give it a name.", "In Unsteady Flow Data, click Area/BC line… to set its boundary condition."]),
      ("Blok BC Line di file .g##.", "BC Line block in the .g## file."), M6, st="preview", rel=["geometry.area2d", "unsteady.area"])
topic("geometry.pump", ("Stasiun pompa", "Pump station"), ("Memompa air dari reach, storage area, atau sel area 2D ke lokasi lain atau keluar sistem.", "Pumps water from a reach, a storage area or a 2D area cell to another location or out of the system."),
      ("Setiap grup pompa menyala bila muka air di sisi isap naik di atas elevasi nyala, dan mati di bawah elevasi mati. Debit = jumlah pompa × kapasitas.", "Each pump group starts when the inlet water surface rises above its on elevation and stops below its off elevation. Flow = number of pumps × capacity."),
      (["Klik Stasiun Pompa di palet, lalu Tambah.", "Pilih asal dan tujuan (penampang reach, storage area, titik di area 2D, atau keluar sistem).", "Isi grup pompa: jumlah, kapasitas, elevasi nyala dan mati."], ["Click Pump Station in the palette, then Add.", "Pick the source and destination (reach cross section, storage area, point in a 2D area, or out of the system).", "Fill the pump groups: count, capacity, on and off elevations."]),
      ("Disimpan di file .deras.json proyek. Blok Pump Station di file .g## yang dibuat HEC-RAS tetap disimpan tetapi belum dibaca.", "Stored in the project's .deras.json. Pump Station blocks in .g## files written by HEC-RAS are kept but not read yet."),
      ("Debit pompa tampil di Hasil. " + M6[0], "Pump flow appears in Results. " + M6[1]), st="preview", rel=["geometry.storage", "geometry.area2d"])
topic("geometry.col.volume", ("Tabel elevasi–volume", "Elevation–volume table"), ("Volume tampungan storage area pada setiap elevasi, elevasi naik.", "Storage volume of the storage area at each elevation, elevations increasing."),
      ("Di antara titik dipakai interpolasi linear. Di atas titik terakhir, volume bertambah dengan luas dari dua titik terakhir.", "Linear interpolation is used between points. Above the last point, the volume grows with the area of the last two points."))
topic("geometry.col.xy", ("Koordinat X–Y", "X–Y coordinates"), ("Titik poligon atau garis dalam koordinat peta, berurutan.", "Polygon or line points in map coordinates, in order."),
      ("Poligon tidak perlu ditutup; titik terakhir disambung otomatis ke titik pertama.", "Polygons need not be closed; the last point joins the first automatically."))
topic("unsteady.area", ("Kondisi batas area", "Area boundary conditions"), ("Kondisi batas untuk storage area dan area 2D.", "Boundary conditions for storage areas and 2D areas."),
      ("Storage area: hidrograf debit masuk, hidrograf muka air, atau hujan. Area 2D: hidrograf debit atau muka air, atau normal depth, lewat BC line; hujan untuk seluruh area. Hujan diisi sebagai tebal per interval (mm atau in). Muka air awal area diisi di tabel kondisi awal; kosong berarti kering (area 2D) atau elevasi minimum (storage area).", "Storage area: inflow hydrograph, stage hydrograph or precipitation. 2D area: flow or stage hydrograph, or normal depth, through a BC line; precipitation over the whole area. Precipitation is entered as depth per interval (mm or in). The initial water surface of an area goes in the initial conditions table; empty means dry (2D area) or the minimum elevation (storage area)."),
      (["Klik Area/BC line….", "Pilih area, BC line (untuk area 2D), dan jenis.", "Klik Tambah, lalu isi hidrografnya."], ["Click Area/BC line….", "Pick the area, the BC line (for a 2D area) and the type.", "Click Add, then fill its hydrograph."]),
      ("Boundary Location di file .u## dengan nama area di kolom ke-6 dan BC line di kolom ke-8.", "Boundary Location in the .u## file with the area name in the 6th field and the BC line in the 8th."), M6, st="preview", rel=["geometry.storage", "geometry.area2d", "geometry.bcline", "unsteady.types"])
topic("mapper.results2d", ("Hasil area 2D", "2D area results"), ("Peta kedalaman, kecepatan, dan waktu tiba dari area 2D sebuah plan unsteady.", "Depth, velocity and arrival time maps from the 2D areas of an unsteady plan."),
      ("Pilih area dan variabel: kedalaman maksimum, kedalaman pada waktu tertentu (geser slider), kecepatan maksimum, atau waktu tiba (jam sejak mulai sampai kedalaman 0,03 m / 0,1 ft). Kedalaman dihitung dari muka air sel dikurangi terrain di setiap piksel. Kecepatan dan waktu tiba bernilai satu per sel. Peta bisa diekspor ke GeoTIFF seperti peta genangan.", "Pick the area and the variable: maximum depth, depth at a time (move the slider), maximum velocity, or arrival time (hours from the start until a depth of 0.03 m / 0.1 ft). Depth is the cell water surface minus the terrain at each pixel. Velocity and arrival time have one value per cell. Maps export to GeoTIFF like inundation maps."),
      d=("Hasil disimpan di <nama>.<plan>.deras-2d.bin di samping file hasil JSON.", "Results are stored in <name>.<plan>.deras-2d.bin next to the JSON results file."),
      r=M6, st="preview", rel=["geometry.area2d", "mapper.inundation", "mapper.export"])

# ---------------- M7 (0.2.3): quasi-unsteady flow and sediment ----------------
M7 = ("Status Pratinjau: hasil belum dibandingkan dengan HEC-RAS. Satu reach, satu ukuran butir (d50), tanpa pemilahan butir atau armoring.", "Preview status: results are not compared with HEC-RAS yet. One reach, one grain size (d50), no grain sorting or armouring.")
topic("sediment.quasi", ("Data Quasi-unsteady", "Quasi-unsteady Flow Data"), ("Rangkaian debit steady berurutan untuk hitungan sedimen: durasi, debit, interval hitung, dan muka air hilir.", "A sequence of steady flows for the sediment computation: duration, flow, computation increment and downstream stage."),
      ("Setiap baris adalah debit yang bertahan selama durasinya. Hidraulika (muka air, kecepatan, kemiringan energi) dihitung ulang dengan solver steady di setiap interval hitung, dan dasar alur diperbarui di antaranya. Muka air hilir kosong berarti normal depth dengan kemiringan yang diisi.", "Each record is a flow held for its duration. The hydraulics (water surface, velocity, energy slope) are recomputed with the steady solver at every computation increment, and the channel bed is updated in between. An empty downstream stage means normal depth with the given slope."),
      (["Pilih file geometri dan reach.", "Isi tabel: durasi (jam), debit, interval hitung (jam), dan bila perlu muka air hilir.", "Periksa grafik hidrograf di kanan."], ["Pick the geometry file and the reach.", "Fill the table: duration (h), flow, computation increment (h) and, if needed, the downstream stage.", "Check the hydrograph plot on the right."]),
      ("Disimpan di file .deras.json proyek (modul sediment). File .q## HEC-RAS belum dibaca atau ditulis.", "Stored in the project's .deras.json (sediment module). HEC-RAS .q## files are not read or written yet."), M7, st="preview", rel=["sediment.data", "sediment.run"])
topic("sediment.data", ("Data Sedimen", "Sediment Data"), ("Fungsi angkutan, sifat butir, gradasi material dasar, kedalaman yang bisa tergerus, dan muatan masuk di hulu.", "Transport function, grain properties, bed gradation, erodible depth and upstream inflow load."),
      ("Dasar yang bergerak adalah titik penampang di antara stasiun tebing; titik itu naik atau turun sama besar. Erosi dibatasi sampai kedalaman yang bisa tergerus di bawah dasar awal. Default porositas 0,4 dan berat jenis 2,65.", "The movable bed is the cross-section points between the bank stations; they move up or down by the same amount. Erosion is limited to the erodible depth below the initial bed. Default porosity 0.4 and specific gravity 2.65."),
      d=("Disimpan di file .deras.json proyek (modul sediment). File .s## HEC-RAS belum dibaca atau ditulis.", "Stored in the project's .deras.json (sediment module). HEC-RAS .s## files are not read or written yet."), r=M7, st="preview", rel=["sediment.function", "sediment.gradation", "sediment.inflow"])
topic("sediment.function", ("Fungsi angkutan sedimen", "Sediment transport function"), ("Persamaan kapasitas angkut di alur utama.", "The transport capacity equation of the main channel."),
      ("Meyer-Peter Müller (1948): angkutan dasar untuk pasir kasar dan kerikil, qs* = 8 (θ' − 0,047)^1,5 dengan koreksi kekasaran butir (n'/n)^1,5, n' = d90^(1/6)/26. Engelund-Hansen (1967): muatan total untuk pasir, qs = 0,05 V² √(d/(g(s−1))) θ^1,5. Yang (1973): muatan total pasir dari daya aliran satuan VS; untuk d50 di atas 2 mm hitungan memberi peringatan. Kecepatan endap memakai rumus Soulsby (1997).", "Meyer-Peter Müller (1948): bed load for coarse sand and gravel, qs* = 8 (θ' − 0.047)^1.5 with the grain roughness correction (n'/n)^1.5, n' = d90^(1/6)/26. Engelund-Hansen (1967): total load for sand, qs = 0.05 V² √(d/(g(s−1))) θ^1.5. Yang (1973): total sand load from the unit stream power VS; a warning is given for d50 above 2 mm. Fall velocity uses Soulsby (1997)."),
      st="preview", rel=["sediment.data"])
topic("sediment.gradation", ("Gradasi material dasar", "Bed gradation"), ("Diameter butir (mm) dan persen lolos dari analisis saringan.", "Grain diameter (mm) and percent finer from a sieve analysis."),
      ("d50 dan d90 diinterpolasi secara logaritmik dari kurva. Hitungan memakai d50 sebagai ukuran wakil; d90 dipakai untuk koreksi kekasaran butir Meyer-Peter Müller.", "d50 and d90 are interpolated logarithmically from the curve. The computation uses d50 as the representative size; d90 is used for the Meyer-Peter Müller grain roughness correction."), st="preview")
topic("sediment.inflow", ("Muatan sedimen masuk", "Sediment inflow"), ("Muatan sedimen yang masuk di penampang paling hulu.", "The sediment load entering at the most upstream section."),
      ("Muatan setimbang: sama dengan kapasitas angkut di penampang hulu, sehingga dasar di sana tetap. Air jernih: tanpa muatan (misalnya di hilir bendungan), dasar hulu tergerus. Rating curve: muatan dari tabel debit–muatan dalam ton per hari.", "Equilibrium load: equal to the transport capacity at the upstream section, so the bed there does not change. Clear water: no load (for example below a dam), the upstream bed erodes. Rating curve: load from a flow–load table in tons per day."), st="preview")
topic("sediment.run", ("Analisis Sedimen", "Sediment Analysis"), ("Menjalankan hitungan sedimen quasi-unsteady dan menampilkan perubahan dasar alur.", "Runs the quasi-unsteady sediment computation and shows the channel bed change."),
      ("Di setiap interval hitung: hidraulika steady → kapasitas angkut di setiap penampang → persamaan Exner (1 − p) B L dz/dt = Qs,masuk − Qs,keluar. Bila dasar akan berubah lebih dari 5 % kedalaman air, langkah dibagi otomatis dan hidraulika dihitung ulang. Neraca massa (masuk − keluar = perubahan dasar) ditampilkan di bawah tabel.", "At every computation increment: steady hydraulics → transport capacity at every section → the Exner equation (1 − p) B L dz/dt = Qs,in − Qs,out. When the bed would change by more than 5 % of the water depth, the step is split automatically and the hydraulics are recomputed. The mass balance (in − out = bed change) is shown below the table."),
      (["Isi Data Quasi-unsteady dan Data Sedimen.", "Atur interval keluaran (jam).", "Klik Hitung sedimen.", "Geser slider waktu untuk melihat profil dasar dan tabel pada waktu itu; Ekspor CSV untuk semua waktu."], ["Fill the Quasi-unsteady Data and Sediment Data.", "Set the output interval (hours).", "Click Compute sediment.", "Move the time slider to see the bed profile and table at that time; Export CSV for all times."]),
      ("Hasil ditulis ke <nama>.deras-sedimen.json di folder proyek.", "Results go to <name>.deras-sedimen.json in the project folder."), M7, st="preview", rel=["sediment.results", "sediment.quasi", "sediment.data"])
topic("sediment.results", ("Hasil sedimen", "Sediment results"), ("Profil dasar awal dan pada waktu terpilih, perubahan dasar terhadap waktu, dan tabel per penampang.", "Initial bed and bed at the selected time, bed change over time, and a table per cross section."),
      ("Muatan di tabel adalah muatan yang keluar dari volume kontrol setiap penampang, dalam ton per hari.", "The load in the table is the load leaving the control volume of each section, in tons per day."), r=M7, st="preview", rel=["sediment.run"])

# ---------------- M8 (0.2.3): autosave, hydraulic design, water quality ----------------
M8 = ("Status Pratinjau: rumus dan hasil belum dibandingkan dengan HEC-RAS. Keputusan desain tetap tanggung jawab perencana.", "Preview status: equations and results are not compared with HEC-RAS yet. Design decisions remain the engineer's responsibility.")
topic("tools.autosave", ("Autosave", "Autosave"), ("Menyimpan salinan pemulihan perubahan yang belum disimpan setiap beberapa menit (0 = mati, bawaan 5 menit).", "Saves a recovery copy of unsaved changes every few minutes (0 = off, default 5 minutes)."),
      ("Salinan pemulihan ditulis ke folder data aplikasi (recovery), bukan ke file proyek, jadi file HEC-RAS tidak berubah sampai Anda menyimpan. Kalau De-RAS tertutup tanpa menyimpan (listrik padam, crash), saat proyek dibuka lagi De-RAS menawarkan untuk memulihkan perubahan itu. Perubahan yang dipulihkan tampil sebagai belum disimpan. Salinan dihapus setelah proyek disimpan atau Anda memilih Jangan simpan saat menutup.", "The recovery copy goes to the application data folder (recovery), not to the project files, so the HEC-RAS files do not change until you save. If De-RAS closes without saving (power cut, crash), it offers to recover those changes the next time the project opens. Recovered changes show as unsaved. The copy is deleted after the project is saved or when you choose Don't save on closing."),
      rel=["options"])
topic("design.uniform", ("Aliran seragam", "Uniform flow"), ("Debit dari kedalaman, atau kedalaman normal dari debit, di saluran trapesium (persamaan Manning).", "Flow from depth, or normal depth from flow, in a trapezoidal channel (Manning's equation)."),
      ("Q = (k/n) A R^(2/3) S^(1/2), k = 1 (SI) atau 1,486 (US). Kedalaman normal dicari dengan metode bagi dua. Kedalaman kritis dari Q²T/(gA³) = 1. Tegangan geser dasar τ = γRS. Talud z = 0 berarti saluran persegi.", "Q = (k/n) A R^(2/3) S^(1/2), k = 1 (SI) or 1.486 (US). The normal depth is found by bisection. Critical depth from Q²T/(gA³) = 1. Bed shear τ = γRS. Side slope z = 0 means a rectangular channel."),
      (["Isi lebar dasar, talud, n dan kemiringan.", "Pilih Debit dari kedalaman atau Kedalaman normal dari debit.", "Isi kedalaman atau debit; hasil dan gambar penampang langsung diperbarui."], ["Enter the bottom width, side slope, n and slope.", "Choose Flow from depth or Normal depth from flow.", "Enter the depth or flow; the results and the cross-section drawing update at once."]),
      r=M8, st="preview", rel=["design.scour", "design.calibration"])
topic("design.scour", ("Gerusan jembatan (HEC-18)", "Bridge scour (HEC-18)"), ("Gerusan pilar, gerusan kontraksi dan gerusan abutmen menurut FHWA HEC-18 edisi ke-5 (2012).", "Pier, contraction and abutment scour after FHWA HEC-18, 5th edition (2012)."),
      ("Pilar (persamaan CSU): ys/a = 2,0 K1 K2 K3 (y1/a)^0,35 Fr1^0,43; K1 dari bentuk ujung (persegi 1,1; bulat dan silinder 1,0; runcing 0,9; K1 = 1 bila sudut serang > 5°), K2 = (cos θ + L/a sin θ)^0,65 dengan L/a paling besar 12, K3 dari kondisi dasar. Untuk pilar ujung bulat yang searah aliran, batas atas 2,4a untuk Fr ≤ 0,8 dan 3,0a di atasnya. Kontraksi dasar hidup (Laursen 1960 termodifikasi): y2/y1 = (Q2/Q1)^(6/7) (W1/W2)^k1, k1 0,59/0,64/0,69 dari V*/ω. Kontraksi air jernih (Laursen 1963): y2 = [Ku Q² / (Dm^(2/3) W²)]^(3/7), Dm = 1,25 D50. Gerusan = y2 − y0. Abutmen (Froehlich 1989): ys/ya = 2,27 K1 K2 (L'/ya)^0,43 Fr^0,61 + 1.", "Pier (CSU equation): ys/a = 2.0 K1 K2 K3 (y1/a)^0.35 Fr1^0.43; K1 from the nose shape (square 1.1; round and circular 1.0; sharp 0.9; K1 = 1 when the attack angle is above 5°), K2 = (cos θ + L/a sin θ)^0.65 with L/a at most 12, K3 from the bed condition. For round-nose piers aligned with the flow, the upper limit is 2.4a for Fr ≤ 0.8 and 3.0a above. Live-bed contraction (modified Laursen 1960): y2/y1 = (Q2/Q1)^(6/7) (W1/W2)^k1, k1 0.59/0.64/0.69 from V*/ω. Clear-water contraction (Laursen 1963): y2 = [Ku Q² / (Dm^(2/3) W²)]^(3/7), Dm = 1.25 D50. Scour = y2 − y0. Abutment (Froehlich 1989): ys/ya = 2.27 K1 K2 (L'/ya)^0.43 Fr^0.61 + 1."),
      (["Pilih plan, profil dan penampang di Ambil nilai dari hasil hitungan, lalu klik Isi dari hasil (atau isi manual).", "Lengkapi data pilar, kontraksi dan abutmen.", "Baca gerusan di bawah setiap kartu dan total di pilar di bagian bawah."], ["Choose the plan, profile and cross section under Take values from computed results, then click Fill from results (or enter values by hand).", "Complete the pier, contraction and abutment data.", "Read the scour below each card and the total at the pier at the bottom."]),
      ("Isi dari hasil memakai y1 = kedalaman maksimum alur utama, V1 = kecepatan alur utama, Q1 = debit alur, Q2 = debit total, S1 = kemiringan energi, Ve = debit/luas bantaran kiri. Nilai ini titik awal; periksa terhadap kondisi jembatan sebenarnya.", "Fill from results uses y1 = maximum main-channel depth, V1 = main-channel velocity, Q1 = channel flow, Q2 = total flow, S1 = energy slope, Ve = left overbank flow/area. These are starting values; check them against the actual bridge."),
      M8, st="preview", rel=["design.uniform", "geometry.bridge"])
topic("design.calibration", ("Kalibrasi n Manning", "Manning's n calibration"), ("Mencari satu faktor pengali n Manning agar muka air hitungan steady paling dekat dengan muka air terukur.", "Finds one factor on Manning's n so that the steady water surfaces come closest to the observed ones."),
      ("De-RAS menjalankan hitungan steady berulang (pencarian golden-section pada log faktor di rentang yang diisi) dan meminimalkan RMS selisih muka air di penampang yang punya pengamatan. Faktor dipakai pada n alur utama saja atau pada semua n. Satu faktor untuk seluruh geometri; variasi n per lokasi belum dikalibrasi.", "De-RAS runs the steady computation repeatedly (golden-section search on the log of the factor within the given range) and minimises the RMS water-surface difference at the sections with observations. The factor applies to the main-channel n only or to every n. One factor for the whole geometry; n by location is not calibrated yet."),
      (["Pilih plan steady dan profil yang sesuai dengan kejadian terukur.", "Isi muka air terukur di kolom terakhir.", "Klik Kalibrasi dan periksa grafik serta RMS.", "Klik Terapkan ke geometri bila hasilnya masuk akal, simpan, lalu hitung ulang."], ["Choose the steady plan and the profile that matches the observed event.", "Enter the observed water surfaces in the last column.", "Click Calibrate and check the plot and the RMS.", "Click Apply to geometry if the result makes sense, save, then compute again."]),
      ("Pengamatan disimpan di .deras.json (modul calibration). Terapkan ke geometri mengalikan n di file geometri plan; perubahan bisa dibatalkan dengan menutup tanpa menyimpan.", "Observations are stored in .deras.json (calibration module). Apply to geometry multiplies the n values in the plan's geometry file; close without saving to undo."),
      M8, st="preview", rel=["design.uniform"])
topic("wq.data", ("Data Kualitas Air", "Water Quality Data"), ("Konstituen, konsentrasi awal, koefisien dispersi, laju peluruhan, dan konsentrasi masuk di hulu.", "Constituent, initial concentration, dispersion coefficient, decay rate and upstream inflow concentration."),
      ("Kualitas air memakai hidraulika (muka air dan debit setiap waktu keluaran) dari hasil unsteady plan yang dipilih, di reach pertama plan itu. Satu konstituen dalam mg/L dengan peluruhan orde-1 (laju per hari, 0 = konservatif). Suhu, DO dan nutrien belum tersedia.", "Water quality uses the hydraulics (water surface and flow at every output time) of the stored unsteady results of the chosen plan, in that plan's first reach. One constituent in mg/L with first-order decay (rate per day, 0 = conservative). Temperature, DO and nutrients are not available yet."),
      (["Pilih plan unsteady yang sudah dihitung.", "Isi nama konstituen, konsentrasi awal, dispersi dan laju peluruhan.", "Isi tabel jam dan konsentrasi di hulu."], ["Choose an unsteady plan that has been computed.", "Enter the constituent name, initial concentration, dispersion and decay rate.", "Fill the table of hours and upstream concentration."]),
      ("Disimpan di .deras.json (modul water_quality). File .w## HEC-RAS belum dibaca atau ditulis.", "Stored in .deras.json (water_quality module). HEC-RAS .w## files are not read or written yet."),
      M8, st="preview", rel=["wq.run"])
topic("wq.run", ("Analisis Kualitas Air", "Water Quality Analysis"), ("Menghitung sebaran konsentrasi sepanjang reach terhadap waktu.", "Computes the concentration along the reach over time."),
      ("Persamaan adveksi-dispersi 1D dengan volume hingga implisit (adveksi upwind, dispersi beda tengah), langkah dibagi agar bilangan Courant sekitar 1. Neraca massa: perubahan simpanan = masuk − keluar − meluruh + koreksi kontinuitas hidraulik. Koreksi muncul karena hidraulika yang tersimpan per waktu keluaran tidak menutup kontinuitas persis; nilainya ditampilkan agar terlihat besarnya (biasanya jauh di bawah 1 % massa masuk).", "1D advection-dispersion with an implicit finite volume scheme (upwind advection, central dispersion); steps are split so that the Courant number is about 1. Mass balance: change in storage = in − out − decayed + hydraulic continuity correction. The correction appears because the stored hydraulics at output times do not close continuity exactly; it is shown so its size is visible (usually far below 1 % of the mass in)."),
      (["Isi Data Kualitas Air.", "Klik Hitung kualitas air.", "Geser slider waktu; grafik kanan menunjukkan konsentrasi di hulu, tengah dan hilir; Ekspor CSV untuk semua waktu."], ["Fill the Water Quality Data.", "Click Compute water quality.", "Move the time slider; the right plot shows the concentration upstream, in the middle and downstream; Export CSV for all times."]),
      ("Hasil ditulis ke <nama>.<plan>.deras-wq.json. Contoh: proyek DerasUji1km memakai pelacak 100 mg/L selama 3 jam pada banjir p02.", "Results go to <name>.<plan>.deras-wq.json. Example: the DerasUji1km project uses a 100 mg/L tracer for 3 hours on the p02 flood."),
      st="preview", rel=["wq.data"])
